window.FE_BANK = {"meta":{"areas":[{"name":"Mathematics and Statistics","short":"Math","low":8,"high":12,"have":10},{"name":"Ethics and Professional Practice","short":"Ethics","low":4,"high":6,"have":5},{"name":"Engineering Economics","short":"Econ","low":5,"high":8,"have":7},{"name":"Statics","short":"Statics","low":8,"high":12,"have":10},{"name":"Dynamics","short":"Dynamics","low":4,"high":6,"have":5},{"name":"Mechanics of Materials","short":"Mech Mat","low":7,"high":11,"have":9},{"name":"Materials","short":"Materials","low":5,"high":8,"have":6},{"name":"Fluid Mechanics","short":"Fluids","low":6,"high":9,"have":8},{"name":"Surveying","short":"Surveying","low":6,"high":9,"have":8},{"name":"Water Resources and Environmental Engineering","short":"Water/Env","low":10,"high":15,"have":12},{"name":"Structural Engineering","short":"Structural","low":10,"high":15,"have":12},{"name":"Geotechnical Engineering","short":"Geotech","low":10,"high":15,"have":12},{"name":"Transportation Engineering","short":"Transpo","low":9,"high":14,"have":11},{"name":"Construction Engineering","short":"Construction","low":8,"high":12,"have":10}],"exam_total":110,"exam_minutes":350,"count":125},"questions":[{"id":"MATH-01","area":"Mathematics and Statistics","topic":"Analytic geometry","prompt":"What is the shortest distance from the point (4, -3) to the line 3x + 4y - 12 = 0?","kind":"mc","diff":1,"units":"units","steps":["Numerator: |3(4) + 4(-3) - 12| = |12 - 12 - 12| = 12","Denominator: sqrt(3^2 + 4^2) = 5","d = 12 / 5 = 2.4"],"formula":"d = |Ax0 + By0 + C| / sqrt(A^2 + B^2)","note":"","pitfall":"The line must be in the form Ax + By + C = 0 before you read off A, B, C. If you are handed y = mx + b, rearrange first.","choices":[{"text":"1.714","why":"You divided by A+B instead of sqrt(A^2+B^2)."},{"text":"2.4","why":null},{"text":"5","why":"That is the distance from the origin to the point, not from the point to the line."},{"text":"12","why":"You stopped at |Ax+By+C| and never divided by sqrt(A^2+B^2). That numerator is not a length."}],"answer":1},{"id":"MATH-02","area":"Mathematics and Statistics","topic":"Single-variable calculus","prompt":"For f(x) = x^3 - 6x^2 + 9x + 2, what is the value of f at the local maximum?","kind":"mc","diff":2,"units":"","steps":["f'(x) = 3x^2 - 12x + 9 = 3(x - 1)(x - 3), so x = 1 and x = 3","f''(x) = 6x - 12. At x = 1, f'' = -6 < 0, so x = 1 is the local max","f(1) = 1 - 6 + 9 + 2 = 6"],"formula":"Critical points: f'(x) = 0. Max if f''(x) < 0, min if f''(x) > 0.","note":"","pitfall":"Answer the question that was asked. 'Where' wants x; 'what is the value' wants f(x). This single reading error is worth several points per exam.","choices":[{"text":"1","why":"That is the x-location of the maximum, not the value of f there."},{"text":"2","why":"x = 3 is the local MINIMUM. f'' = 6x - 12 is positive there."},{"text":"4","why":"You dropped the constant term. f(1) = 1 - 6 + 9 + 2, and the +2 counts."},{"text":"6","why":null}],"answer":3},{"id":"MATH-03","area":"Mathematics and Statistics","topic":"Single-variable calculus","prompt":"Find the area bounded by y = x^2, the x-axis, and the line x = 3.","kind":"num","diff":1,"units":"square units","steps":["A = integral(0 to 3) x^2 dx = [x^3 / 3] from 0 to 3","A = 27/3 - 0 = 9"],"formula":"A = integral from a to b of f(x) dx; integral of x^n = x^(n+1)/(n+1)","note":"","pitfall":"Raising to n+1 and then forgetting to divide by n+1 is the single most common integration slip under time pressure.","answer":9.0,"tol":0.01},{"id":"MATH-04","area":"Mathematics and Statistics","topic":"Vector operations","prompt":"Given A = 2i - j + 3k and B = i + 4j - 2k, what is the angle between A and B?","kind":"mc","diff":2,"units":"degrees","steps":["A dot B = (2)(1) + (-1)(4) + (3)(-2) = 2 - 4 - 6 = -8","|A| = sqrt(4 + 1 + 9) = 3.742, |B| = sqrt(1 + 16 + 4) = 4.583","cos(theta) = -8 / (3.742 x 4.583) = -0.4666","theta = 117.8 degrees"],"formula":"A dot B = |A||B| cos(theta)","note":"","pitfall":"A negative dot product is a result, not an error. Do not 'fix' it.","choices":[{"text":"45.58","why":"You multiplied the component magnitudes and lost the minus signs: 2 + 4 + 6 = 12 instead of 2 - 4 - 6."},{"text":"62.19","why":"You dropped the negative sign on the dot product. A negative dot product means the angle is obtuse (greater than 90 degrees)."},{"text":"90","why":"The vectors are only perpendicular if A dot B = 0. Here it is -8."},{"text":"117.8","why":null}],"answer":3},{"id":"MATH-05","area":"Mathematics and Statistics","topic":"Vector operations","prompt":"Vectors P = 3i + j and Q = i + 4j form two sides of a parallelogram. What is its area?","kind":"num","diff":2,"units":"square units","steps":["P x Q = (1*0 - 0*4)i - (3*0 - 0*1)j + (3*4 - 1*1)k = 11k","|P x Q| = 11"],"formula":"Area of parallelogram = |P x Q|; triangle = |P x Q| / 2","note":"","pitfall":"A TRIANGLE formed by the same two vectors is half this. Read whether the question says triangle or parallelogram.","answer":11.0,"tol":0.01},{"id":"MATH-06","area":"Mathematics and Statistics","topic":"Statistics","prompt":"A sample of five measurements reads 12, 15, 18, 20, and 25. What is the sample standard deviation?","kind":"mc","diff":2,"units":"","steps":["xbar = 90 / 5 = 18","Deviations: -6, -3, 0, 2, 7 -> squares 36, 9, 0, 4, 49, sum = 98","s = sqrt(98 / 4) = 4.95"],"formula":"s = sqrt( sum(xi - xbar)^2 / (n - 1) )   [sample]\nsigma = sqrt( sum(xi - mu)^2 / n )        [population]","note":"","pitfall":"The handbook lists both forms. 'Sample' means n - 1. The FE will offer the n version as a distractor every time.","choices":[{"text":"4.427","why":"You divided by n. The SAMPLE standard deviation divides by n - 1 (Bessel's correction)."},{"text":"4.95","why":null},{"text":"18","why":"That is the mean, not the standard deviation."},{"text":"24.5","why":"That is the sample VARIANCE. Take the square root."}],"answer":1},{"id":"MATH-07","area":"Mathematics and Statistics","topic":"Statistics","prompt":"Concrete cylinder strengths are normally distributed with a mean of 100 and a standard deviation of 12. What is the probability that a cylinder exceeds 118?","kind":"mc","diff":2,"units":"","steps":["z = (118 - 100) / 12 = 1.5","Phi(1.5) = 0.9332","P(X > 118) = 1 - 0.9332 = 0.0668"],"formula":"z = (x - mu) / sigma ; P(X > x) = 1 - Phi(z)","note":"","pitfall":"Sketch the bell curve and shade what you want before touching the table. Tail-direction errors are the #1 statistics loss on the FE.","choices":[{"text":"0","why":"You used x/sigma instead of (x - mu)/sigma. Subtract the mean first."},{"text":"0.0668","why":null},{"text":"0.1336","why":"You doubled for two tails. Only the upper tail was asked for."},{"text":"0.9332","why":"That is P(X < 118). The question asks for the upper tail, so subtract from 1."}],"answer":1},{"id":"MATH-08","area":"Mathematics and Statistics","topic":"Statistics","prompt":"A least-squares line is fit to the points (1, 2), (2, 5), (3, 7), (4, 10). What is the slope?","kind":"mc","diff":2,"units":"","steps":["n = 4, Sx = 10, Sy = 24, Sxy = 73, Sxx = 30","m = (4*73 - 10*24) / (4*30 - 10^2)","m = 52 / 20 = 2.6"],"formula":"m = (n*Sxy - Sx*Sy) / (n*Sxx - (Sx)^2) ;  b = (Sy - m*Sx) / n","note":"","pitfall":"Here the two-point shortcut gives 2.67 and least squares gives 2.6. Close enough to look right, far enough to be a wrong option.","choices":[{"text":"-0.5","why":"That is the y-intercept."},{"text":"2.4","why":"That is the ratio of the sums, which is not the regression slope."},{"text":"2.6","why":null},{"text":"2.667","why":"You used only the first and last points. Least squares uses all of them."}],"answer":2},{"id":"MATH-09","area":"Mathematics and Statistics","topic":"Statistics","prompt":"A survey crew of 3 is to be chosen from 8 available technicians. How many different crews are possible?","kind":"mc","diff":1,"units":"","steps":["Order does not matter for a crew, so use combinations","C(8, 3) = 8! / (3! 5!) = (8 x 7 x 6) / (3 x 2 x 1) = 56"],"formula":"C(n, r) = n! / (r! (n - r)!) ;  P(n, r) = n! / (n - r)!","note":"","pitfall":"'Crew', 'committee', 'sample' -> combinations. 'Ranking', 'schedule', 'president and vice-president' -> permutations.","choices":[{"text":"24","why":"Multiplying the two numbers is not a counting rule."},{"text":"56","why":null},{"text":"112","why":"No reason to double a combination count."},{"text":"336","why":"That is PERMUTATIONS, which counts order. A crew is a set, so order does not matter."}],"answer":1},{"id":"MATH-10","area":"Mathematics and Statistics","topic":"Statistics","prompt":"A sample of 25 specimens has a mean of 50 and a standard deviation of 5. Using z = 1.96 for 95% confidence, what is the half-width of the confidence interval on the mean?","kind":"num","diff":2,"units":"","steps":["Standard error = s / sqrt(n) = 5 / sqrt(25) = 1","Half-width = 1.96 x 1 = 1.96","So the interval is 50 +/- 1.96"],"formula":"CI = xbar +/- z * s / sqrt(n)","note":"","pitfall":"Dividing by n instead of sqrt(n) is the classic slip. For n = 25 that is an error of 5x.","answer":1.9600000000000002,"tol":0.02},{"id":"ETH-01","area":"Ethics and Professional Practice","topic":"Codes of ethics","prompt":"A licensed civil engineer is asked by a developer to stamp and seal a set of structural drawings prepared by an out-of-state firm that the engineer did not supervise. The drawings appear competent. What is the engineer's obligation?","kind":"mc","diff":1,"units":"","steps":["Plan stamping is the textbook licensure violation","The only cure is actually being in responsible charge, which cannot be created retroactively","The engineer must decline, and may offer to be engaged early enough on a future project to genuinely supervise"],"formula":"Responsible charge: seal only work you performed or directly supervised.","note":"","pitfall":"If an ethics option contains 'indemnification', 'hold harmless', or 'the client accepts the risk', it is almost always the wrong answer.","choices":[{"text":"Decline to seal them, because an engineer may only seal work performed by or under their responsible charge","why":null},{"text":"Seal them, since a review confirmed the drawings are technically adequate","why":"Technical adequacy is not the test. Sealing certifies responsible charge, which a review after the fact does not create."},{"text":"Seal them if the developer provides written indemnification","why":"An engineer cannot contract away a licensure obligation. Indemnity shifts money, not responsibility."},{"text":"Seal them if the out-of-state firm is itself licensed somewhere","why":"Another firm's license does not transfer responsible charge to this engineer."}],"answer":0},{"id":"ETH-02","area":"Ethics and Professional Practice","topic":"Codes of ethics","prompt":"During construction an engineer discovers that an already-poured foundation has significantly less reinforcement than the design requires. The contractor asks the engineer to say nothing, promising to compensate elsewhere. What must the engineer do first?","kind":"mc","diff":1,"units":"","steps":["Rank the duties: public safety outranks client, employer, and contractor","A known structural deficiency is a public-safety matter","Disclose to the owner and the authority having jurisdiction; then evaluate an engineered repair"],"formula":"First canon: hold paramount the safety, health, and welfare of the public.","note":"","pitfall":"'Paramount' is a ranking word. When an ethics question pits safety against anything else, safety wins with no balancing test.","choices":[{"text":"Notify the owner and the appropriate authority, because protection of public health and safety is the engineer's paramount obligation","why":null},{"text":"Accept the contractor's remedy if calculations show the structure still works","why":"The engineer may well accept an engineered repair, but concealment is not available. Disclosure comes first, then the fix."},{"text":"Say nothing, since the engineer owes a duty of loyalty to project participants","why":"Loyalty to a client or contractor never outranks public safety. This is the first canon."},{"text":"Resign from the project to avoid being implicated","why":"Walking away leaves the hazard in place and un-reported. Resignation is not disclosure."}],"answer":0},{"id":"ETH-03","area":"Ethics and Professional Practice","topic":"Professional liability","prompt":"An engineer whose practice is entirely in transportation design is offered a structural seismic retrofit commission. What is the most appropriate response?","kind":"mc","diff":2,"units":"","steps":["The license may be general, but the ethical limit is demonstrated competence","Two acceptable paths: be genuinely qualified, or associate with someone who is and who takes responsible charge","Either way the public gets a competent engineer on the seismic scope"],"formula":"Perform services only in your areas of competence.","note":"","pitfall":"Watch for 'in all cases' and 'never'. Correct ethics answers usually allow a legitimate path forward.","choices":[{"text":"Accept only if qualified by education or experience in that specialty, or associate with a qualified engineer who takes responsible charge of that work","why":null},{"text":"Accept, because a professional engineer's license is not limited by discipline","why":"Most licenses are general in law but the codes of ethics restrict practice to areas of actual competence."},{"text":"Accept and learn the specialty during the project, billing the research time","why":"Self-education on a live project puts the public at risk and bills the client for your training."},{"text":"Decline in all cases, since changing specialty is not permitted","why":"Too absolute. Associating with a qualified engineer is a recognized and proper route."}],"answer":0},{"id":"ETH-04","area":"Ethics and Professional Practice","topic":"Contracts and contract law","prompt":"An engineer serving as an independent reviewer for a city holds a small ownership stake in the firm whose design is under review. What is required?","kind":"mc","diff":2,"units":"","steps":["Any financial interest in the reviewed party is a conflict","The remedy is disclosure to the client, in writing","The client, not the engineer, decides whether to waive it"],"formula":"Disclose all known or potential conflicts of interest promptly and in writing.","note":"","pitfall":"Conflict-of-interest answers are about PROCESS, not magnitude. 'Too small to matter' is never the correct reasoning.","choices":[{"text":"Disclose the financial interest in writing to the city, and withdraw unless the city knowingly consents","why":null},{"text":"Nothing, provided the ownership stake is too small to influence judgment","why":"The engineer does not get to decide what is material. Disclosure lets the client decide."},{"text":"Sell the stake quietly and continue the review without mentioning it","why":"Divestment does not erase the conflict during the period it existed, and concealment compounds it."},{"text":"Continue, because a reviewer's duty runs to the public rather than the city","why":"The public duty does not cancel the disclosure duty. Both apply."}],"answer":0},{"id":"ETH-05","area":"Ethics and Professional Practice","topic":"Licensure","prompt":"Which activity most clearly requires a professional engineering license?","kind":"mc","diff":1,"units":"","steps":["Look for the combination of public safety plus a document that gets sealed","Structural calculations for a public building hit both","The other three are recognized exemption categories: supervised work, teaching, and manufacturing"],"formula":"Licensure attaches to offering or performing engineering services for the public, and to sealing documents.","note":"","pitfall":"Learn the exemption families (industrial, supervised, teaching, federal employment). FE licensure questions are almost always testing one of them.","choices":[{"text":"Preparing and sealing structural calculations for a public building","why":null},{"text":"Operating surveying equipment as a crew member under a licensed surveyor","why":"Working under direct supervision is specifically how unlicensed staff may contribute."},{"text":"Teaching an undergraduate statics course","why":"Teaching is generally exempt; it is not the practice of engineering for a client."},{"text":"Selling manufactured steel connectors with published load tables","why":"This typically falls under the industrial or manufacturer exemption."}],"answer":0},{"id":"ECON-01","area":"Engineering Economics","topic":"Time value of money","prompt":"A maintenance contract costs $10,000 at the end of each year for 8 years. At an interest rate of 6%, what is the present worth?","kind":"mc","diff":2,"units":"$","steps":["(P/A, 6%, 8) = [1 - 1.06^-8] / 0.06 = 6.21","PW = 10,000 x 6.21 = $62,098"],"formula":"(P/A, i, n) = [1 - (1 + i)^-n] / i","note":"","pitfall":"Confirm whether payments land at the END of each period (ordinary annuity, which these factors assume) or the BEGINNING (annuity due, multiply by 1 + i).","choices":[{"text":"62,098","why":null},{"text":"80,000","why":"You summed the payments without discounting. $80,000 is the undiscounted total, not the present worth."},{"text":"98,975","why":"That is the FUTURE worth (F/A), not the present worth (P/A)."},{"text":"166,667","why":"That is a perpetuity (A/i), which assumes payments forever rather than 8 years."}],"answer":0},{"id":"ECON-02","area":"Engineering Economics","topic":"Time value of money","prompt":"What is the future worth of $25,000 invested for 10 years at 7% compounded annually?","kind":"num","diff":1,"units":"$","steps":["(1.07)^10 = 1.9672","F = 25,000 x 1.9672 = $49,179"],"formula":"F = P (1 + i)^n","note":"","pitfall":"Simple interest would give 25,000(1 + 0.07*10) = $42,500. The FE means compound interest unless it says otherwise.","answer":49179.0,"tol":0.01},{"id":"ECON-03","area":"Engineering Economics","topic":"Analyses","prompt":"A machine costs $80,000, has a 5-year life, and a salvage value of $10,000. At 10% interest, what is the equivalent uniform annual cost?","kind":"mc","diff":3,"units":"$/yr","steps":["(A/P, 10%, 5) = 0.10(1.1^5) / (1.1^5 - 1) = 0.2638","(A/F, 10%, 5) = 0.10 / (1.1^5 - 1) = 0.1638","EUAC = 80,000(0.2638) - 10,000(0.1638) = $19,466"],"formula":"EUAC = P(A/P, i, n) - S(A/F, i, n)","note":"","pitfall":"(A/P) and (A/F) differ by exactly i: A/P = A/F + i. Use that as a 10-second check on both factors.","choices":[{"text":"14,000","why":"That is straight-line depreciation, which ignores the time value of money entirely."},{"text":"19,466","why":null},{"text":"21,104","why":"You ignored the salvage credit. Salvage reduces the annual cost via (A/F)."},{"text":"22,742","why":"Sign error: salvage is income, so it is SUBTRACTED from the annual cost."}],"answer":1},{"id":"ECON-04","area":"Engineering Economics","topic":"Analyses","prompt":"A plant has fixed costs of $50,000 per year, a variable cost of $15 per unit, and sells units at $40. How many units per year must it sell to break even?","kind":"num","diff":1,"units":"units/yr","steps":["Contribution margin per unit = 40 - 15 = $25","Q = 50,000 / 25 = 2,000 units"],"formula":"Break-even quantity = Fixed cost / (price - variable cost)","note":"","pitfall":"Divide by the MARGIN, not by the price. Using 50,000/40 gives 1,250 and will be on the answer list.","answer":2000.0,"tol":0.01},{"id":"ECON-05","area":"Engineering Economics","topic":"Analyses","prompt":"A public project has benefits with a present worth of $1,200,000 and costs with a present worth of $800,000. What is the benefit-cost ratio, and is the project justified?","kind":"mc","diff":1,"units":"","steps":["B/C = 1,200,000 / 800,000 = 1.5","1.5 > 1.0, so the project is economically justified"],"formula":"B/C = PW(benefits) / PW(costs). Accept if B/C >= 1.","note":"","pitfall":"Conventional B/C puts disbenefits in the numerator as a subtraction, while modified B/C moves annual O&M to the numerator. Both appear on the FE.","choices":[{"text":"1.5 - justified, because B/C is greater than 1","why":null},{"text":"0.6667 - not justified","why":"You inverted the ratio. Benefits go on top."},{"text":"400,000 - justified","why":"That is net present worth in dollars, not a ratio."},{"text":"1.5 - marginal, so defer the project","why":"The ratio is correct but the conclusion is not. Anything above 1.0 is economically justified."}],"answer":0},{"id":"ECON-06","area":"Engineering Economics","topic":"Cost","prompt":"Equipment costing $120,000 saves $32,000 per year. What is the simple payback period, ignoring interest?","kind":"num","diff":1,"units":"years","steps":["Payback = 120,000 / 32,000 = 3.75 years"],"formula":"Simple payback = initial cost / annual net savings","note":"","pitfall":"Simple payback ignores interest and anything after payback. A discounted payback at a nonzero rate is always LONGER.","answer":3.75,"tol":0.02},{"id":"ECON-07","area":"Engineering Economics","topic":"Uncertainty","prompt":"A bid has a 30% chance of losing $20,000 and a 70% chance of earning $50,000. What is the expected value?","kind":"mc","diff":2,"units":"$","steps":["E = 0.30(-20,000) + 0.70(50,000)","E = -6,000 + 35,000 = $29,000","Positive expected value, so the bid is favorable on average"],"formula":"E[X] = sum( p_i * x_i )","note":"","pitfall":"Probabilities must sum to 1.0. If they do not, you have missed an outcome branch.","choices":[{"text":"9,000","why":"The loss is double-counted."},{"text":"15,000","why":"You averaged the outcomes instead of weighting them by probability."},{"text":"29,000","why":null},{"text":"35,000","why":"You kept only the favorable branch. The loss branch is part of the expectation."}],"answer":2},{"id":"STAT-01","area":"Statics","topic":"Resultants of force systems","prompt":"Two forces act at a point: 60 kN directed east and 80 kN directed north. What is the magnitude of the resultant?","kind":"mc","diff":1,"units":"kN","steps":["The forces are perpendicular, so R = sqrt(60^2 + 80^2)","R = sqrt(3600 + 6400) = sqrt(10000) = 100 kN","Direction: arctan(80/60) = 53.13 degrees north of east"],"formula":"R = sqrt(Fx^2 + Fy^2) ;  theta = arctan(Fy / Fx)","note":"","pitfall":"A 3-4-5 triangle hiding in the numbers (60-80-100) is a hint you set it up right. Learn to spot 5-12-13 too.","choices":[{"text":"20","why":"Subtracting applies only to opposing collinear forces."},{"text":"69.28","why":"The geometric mean is not a vector operation."},{"text":"100","why":null},{"text":"140","why":"You added the magnitudes. Forces add as vectors, not scalars, unless they are collinear."}],"answer":2},{"id":"STAT-02","area":"Statics","topic":"Resultants of force systems","prompt":"Three concurrent forces act in a plane: 100 N at 30 degrees, 150 N at 120 degrees, and 80 N at 225 degrees, all measured counterclockwise from the +x axis. What is the magnitude of the resultant?","kind":"mc","diff":2,"units":"N","steps":["Fx = 100cos30 + 150cos120 + 80cos225 = 86.6 - 75.0 - 56.6 = -44.97","Fy = 100sin30 + 150sin120 + 80sin225 = 50.0 + 129.9 - 56.6 = 123.3","R = sqrt((-44.97)^2 + (123.3)^2) = 131.3 N","Direction = 110 degrees from +x (second quadrant)"],"formula":"Fx = sum(F cos a), Fy = sum(F sin a), R = sqrt(Fx^2 + Fy^2)","note":"","pitfall":"Track component signs in a small table. Quadrant errors, not trigonometry, cause most lost points here.","choices":[{"text":"78.37","why":"Component differences are not resultants."},{"text":"131.3","why":null},{"text":"168.3","why":"You added the component magnitudes instead of taking the square root of the sum of squares."},{"text":"330","why":"You summed the magnitudes. These forces point in different directions."}],"answer":1},{"id":"STAT-03","area":"Statics","topic":"Equilibrium of rigid bodies","prompt":"A simply supported beam spans 12 m. A 30 kN point load acts 4 m from the left support A. What is the reaction at A?","kind":"mc","diff":1,"units":"kN","steps":["Moments about B: RA(12) - 30(12 - 4) = 0","RA = 30(8) / 12 = 20 kN","Check: RB = 30 - 20 = 10 kN, and the near support takes the larger share"],"formula":"Sum of moments about B = 0 ;  Sum of Fy = 0","note":"","pitfall":"The reaction at a support is proportional to the distance to the FAR support. Loading near A puts most of the load into A.","choices":[{"text":"10","why":"That is the reaction at B, the FAR support. The near support carries more."},{"text":"15","why":"The load is not at midspan, so the reactions are not equal."},{"text":"20","why":null},{"text":"30","why":"One support does not carry the entire load."}],"answer":2},{"id":"STAT-04","area":"Statics","topic":"Equilibrium of rigid bodies","prompt":"A simply supported beam spans 10 m, carries a uniform load of 12 kN/m over its full length, and a 50 kN point load 3 m from support A. What is the reaction at A?","kind":"mc","diff":2,"units":"kN","steps":["Uniform load total W = 12(10) = 120 kN acting at midspan, 5 m from A","Moments about A: RB(10) = 120(5) + 50(3) = 600 + 150 = 750","RB = 75 kN","RA = 120 + 50 - 75 = 95 kN"],"formula":"Replace a UDL by W = wL acting at its centroid (midspan for uniform).","note":"","pitfall":"Convert every distributed load to a single resultant at its centroid BEFORE writing moment equations. Mixing the two forms is where errors enter.","choices":[{"text":"75","why":"That is the reaction at B."},{"text":"85","why":"Equal reactions would require a symmetric load. The point load is not centered."},{"text":"95","why":null},{"text":"110","why":"You gave B's share of the uniform load but all of the point load to A."}],"answer":2},{"id":"STAT-05","area":"Statics","topic":"Centroid of area","prompt":"An L-shaped area is made of a vertical rectangle 100 mm wide by 300 mm tall (occupying x = 0 to 100, y = 0 to 300) and a horizontal rectangle 150 mm wide by 100 mm tall (x = 100 to 250, y = 0 to 100). How far is the centroid above the base?","kind":"mc","diff":2,"units":"mm","steps":["Piece 1: A = 30,000 mm^2 at y = 150 mm","Piece 2: A = 15,000 mm^2 at y = 50 mm","ybar = [30,000(150) + 15,000(50)] / 45,000 ","ybar = 116.7 mm"],"formula":"ybar = sum(Ai * yi) / sum(Ai)","note":"","pitfall":"Area-weight, never average. And for a shape with a hole, subtract the hole's area and its A*y term.","choices":[{"text":"91.67","why":"That is the horizontal centroid location, x-bar."},{"text":"100","why":"You averaged the two centroid heights without weighting by area. The larger piece pulls harder."},{"text":"116.7","why":null},{"text":"150","why":"That would be the centroid of the vertical leg alone."}],"answer":2},{"id":"STAT-06","area":"Statics","topic":"Area moments of inertia","prompt":"A rectangle is 200 mm wide and 300 mm deep. What is its area moment of inertia about the horizontal axis through its BASE?","kind":"mc","diff":2,"units":"mm^4","steps":["I_centroid = 200(300)^3 / 12 = 450,000,000 mm^4","Parallel axis: d = 150 mm, A = 60,000 mm^2, A*d^2 = 1,350,000,000 mm^4","I_base = 450,000,000 + 1,350,000,000 = 1,800,000,000 mm^4","Equivalently bh^3/3 directly"],"formula":"I_centroid = bh^3/12 ;  I_base = bh^3/3 = I_centroid + A*d^2","note":"","pitfall":"The parallel-axis theorem only moves AWAY from the centroid. You cannot add A*d^2 twice between two non-centroidal axes.","choices":[{"text":"150,000,000","why":"bh^3/36 is for a TRIANGLE about its centroid."},{"text":"200,000,000","why":"You swapped b and h. The depth dimension gets cubed for bending about a horizontal axis."},{"text":"450,000,000","why":"That is I about the CENTROIDAL axis. Use the parallel-axis theorem to move it to the base."},{"text":"1,800,000,000","why":null}],"answer":3},{"id":"STAT-07","area":"Statics","topic":"Static friction","prompt":"A block rests on an inclined plane. The coefficient of static friction is 0.35. At what incline angle does the block begin to slide?","kind":"num","diff":2,"units":"degrees","steps":["Along the slope: W sin(theta) = mu * W cos(theta)","Weight cancels, so tan(theta) = mu = 0.35","theta = arctan(0.35) = 19.29 degrees"],"formula":"At impending slip on an incline: tan(theta) = mu_s","note":"","pitfall":"The angle of repose is independent of weight. If your answer contains the block's mass, you did not cancel W.","answer":19.290046219188735,"tol":0.02},{"id":"STAT-08","area":"Statics","topic":"Static friction","prompt":"An 800 N block sits on a 20 degree incline with a static friction coefficient of 0.30. What force, applied parallel to and up the incline, is required to prevent the block from sliding down?","kind":"mc","diff":3,"units":"N","steps":["Driving force down slope = 800 sin20 = 273.6 N","Maximum friction = 0.30(800 cos20) = 225.5 N","Since 273.6 > 225.5, the block would slide; required force = 273.6 - 225.5 = 48.09 N"],"formula":"F = W sin(theta) - mu_s * W cos(theta)   [block tending to slide down]","note":"","pitfall":"First test whether the block even moves. If max friction exceeds the driving force, the required force is ZERO and friction is not fully developed.","choices":[{"text":"48.09","why":null},{"text":"240","why":"Normal force is W cos(theta) on an incline, not W."},{"text":"273.6","why":"You ignored friction entirely. Friction already resists part of the sliding tendency."},{"text":"499.1","why":"Sign error: friction acts UP the slope when the block tends to slide down, so it helps you."}],"answer":0},{"id":"STAT-09","area":"Statics","topic":"Frames and trusses","prompt":"At a truss joint, a 20 kN downward load is carried by one diagonal member inclined 40 degrees above the horizontal and one horizontal member. What is the force in the diagonal?","kind":"mc","diff":2,"units":"kN","steps":["Vertical equilibrium at the joint: T sin40 = 20","T = 20 / sin40 = 20 / 0.643 = 31.11 kN","Horizontal member then carries T cos40 = 23.84 kN"],"formula":"At a joint: sum Fy = 0 -> T sin(theta) = P","note":"","pitfall":"A diagonal force is always larger in magnitude than the load component it resolves. If your diagonal came out smaller than 20 kN, you divided the wrong way.","choices":[{"text":"12.86","why":"You multiplied by sin instead of dividing. The diagonal must be LARGER than the vertical load it resolves."},{"text":"23.84","why":"That is the force in the horizontal member."},{"text":"26.11","why":"You used cos. The vertical equilibrium equation involves the sine of the angle from horizontal."},{"text":"31.11","why":null}],"answer":3},{"id":"STAT-10","area":"Statics","topic":"Equivalent force systems","prompt":"A triangular distributed load varies from zero at the left end to 18 kN/m at the right end over a 6 m span. What is the magnitude of the resultant, and where does it act measured from the RIGHT (maximum) end?","kind":"mc","diff":2,"units":"","steps":["R = area under the load diagram = 0.5(18)(6) = 54 kN","Centroid of a triangle is L/3 from the wide (maximum) end","Location = 6/3 = 2 m from the right end"],"formula":"Triangular load: R = (1/2) w_max L, acting L/3 from the maximum end","note":"","pitfall":"Read the reference end carefully. L/3 and 2L/3 both appear in the options precisely because this is where students lose the point.","choices":[{"text":"54 kN, 2 m from the right end","why":null},{"text":"108 kN, 2 m from the right end","why":"You used the full rectangle wL. A triangle's area is half that."},{"text":"54 kN, 3 m from the right end","why":"Magnitude is right but the centroid of a triangle is at L/3 from its base, not midspan."},{"text":"54 kN, 4 m from the right end","why":"That is L/3 from the ZERO end, which is 2L/3 from the maximum end. Check which end the question measures from."}],"answer":0},{"id":"DYN-01","area":"Dynamics","topic":"Kinematics","prompt":"A car traveling at 25 m/s brakes to a complete stop in 60 m. Assuming constant deceleration, what is the magnitude of the acceleration?","kind":"num","diff":1,"units":"m/s^2","steps":["0 = 25^2 + 2a(60)","a = -625 / 120 = -5.208 m/s^2","Magnitude = 5.208 m/s^2"],"formula":"v^2 = v0^2 + 2 a s","note":"","pitfall":"Use the equation that does NOT contain time when time is neither given nor asked. Solving for t first doubles your work and your error chances.","answer":5.208333333333333,"tol":0.02},{"id":"DYN-02","area":"Dynamics","topic":"Mass moments of inertia","prompt":"A slender uniform rod has a mass of 12 kg and a length of 2 m. What is its mass moment of inertia about an axis through one END, perpendicular to the rod?","kind":"mc","diff":2,"units":"kg*m^2","steps":["I_centroid = 12(2)^2 / 12 = 4 kg*m^2","Shift to the end: m(L/2)^2 = 12(1)^2 = 12 kg*m^2","I_end = 4 + 12 = 16 kg*m^2"],"formula":"Rod about centroid: mL^2/12. About end: mL^2/3 = mL^2/12 + m(L/2)^2","note":"","pitfall":"mL^2/12 and mL^2/3 differ by a factor of 4. Always confirm which axis the question names before reaching for a formula.","choices":[{"text":"4","why":"That is about the CENTROID. Add m*d^2 with d = L/2 to shift it to the end."},{"text":"16","why":null},{"text":"24","why":"mL^2/2 is the formula for a solid cylinder about its own axis, not a rod."},{"text":"48","why":"You omitted the coefficient entirely."}],"answer":1},{"id":"DYN-03","area":"Dynamics","topic":"Force acceleration","prompt":"A 50 kg crate on a level floor is pulled by a 200 N horizontal force. The kinetic friction coefficient is 0.25. What is the acceleration? Use g = 9.81 m/s^2.","kind":"mc","diff":2,"units":"m/s^2","steps":["Normal force N = 50(9.81) = 490.5 N","Friction = 0.25(490.5) = 122.6 N","Net force = 200 - 122.6 = 77.38 N","a = 77.38 / 50 = 1.548 m/s^2"],"formula":"sum F = ma ;  f_k = mu_k * N ;  N = mg on a level surface","note":"","pitfall":"If the net force comes out negative and the crate was at rest, it does not accelerate backward; it simply does not move.","choices":[{"text":"1.548","why":null},{"text":"2.453","why":"That is the deceleration friction alone would cause."},{"text":"4","why":"You ignored friction. Only the NET force produces acceleration."},{"text":"6.452","why":"Friction opposes motion, so it is subtracted."}],"answer":0},{"id":"DYN-04","area":"Dynamics","topic":"Work, energy, and power","prompt":"A spring with stiffness 800 N/m is compressed 0.15 m and released against a 2 kg block on a frictionless surface. What speed does the block reach?","kind":"num","diff":2,"units":"m/s","steps":["Stored energy = 0.5(800)(0.15)^2 = 9 J","Set equal to kinetic energy: 0.5(2)v^2 = 9","v = sqrt(2 x 9 / 2) = 3 m/s"],"formula":"Spring energy = (1/2) k x^2 ;  Kinetic energy = (1/2) m v^2","note":"","pitfall":"The displacement is SQUARED in spring energy. Doubling the compression quadruples the energy and only doubles the speed.","answer":3.0,"tol":0.02},{"id":"DYN-05","area":"Dynamics","topic":"Work, energy, and power","prompt":"A vehicle overcomes 1500 N of total resistance while traveling at a steady 20 m/s. What power is required?","kind":"mc","diff":1,"units":"kW","steps":["P = 1500(20) = 30,000 W","= 30 kW"],"formula":"P = F v   (for force along the direction of motion)","note":"","pitfall":"Steady speed means zero net force, so the engine force exactly equals resistance. That is why no mass or acceleration appears.","choices":[{"text":"0.075","why":"You divided instead of multiplying. P = Fv."},{"text":"15","why":"The factor of one half belongs to kinetic energy, not power."},{"text":"30","why":null},{"text":"1,800","why":"You multiplied by 60 as if converting to per-minute. Power in watts already is per second."}],"answer":2},{"id":"MECH-01","area":"Mechanics of Materials","topic":"Stresses and strains","prompt":"A steel rod 25 mm in diameter carries an axial tensile load of 60 kN. What is the normal stress?","kind":"mc","diff":1,"units":"MPa","steps":["A = pi(25)^2 / 4 = 490.9 mm^2","sigma = 60,000 N / 490.9 mm^2 = 122.2 MPa"],"formula":"sigma = P / A ;  A_circle = pi d^2 / 4","note":"","pitfall":"1 N/mm^2 is exactly 1 MPa. Working in newtons and millimetres gives MPa directly and removes a whole class of unit errors.","choices":[{"text":"30.56","why":"You used pi*d^2 for area. The area of a circle is pi*d^2/4."},{"text":"96","why":"You used the area of a 25 mm SQUARE, not a circle."},{"text":"122.2","why":null},{"text":"763.9","why":"That is load over circumference, not over area."}],"answer":2},{"id":"MECH-02","area":"Mechanics of Materials","topic":"Deformations","prompt":"The same 25 mm diameter steel rod is 2 m long with E = 200 GPa and carries 60 kN. How much does it elongate?","kind":"num","diff":2,"units":"mm","steps":["A = 490.9 mm^2, L = 2000 mm, E = 200,000 MPa","delta = 60,000(2000) / (490.9 x 200,000)","delta = 1.222 mm"],"formula":"delta = P L / (A E)","note":"","pitfall":"Keep every length in mm and every stress in MPa. Mixing metres with MPa throws the answer off by 1000.","answer":1.2223099629457561,"tol":0.02},{"id":"MECH-03","area":"Mechanics of Materials","topic":"Stresses and strains","prompt":"A steel bar is held between two rigid, immovable supports and heated 40 degrees C. With alpha = 11.7e-6 per degree C and E = 200 GPa, what thermal stress develops?","kind":"mc","diff":2,"units":"MPa (compression)","steps":["Unrestrained strain would be 11.7e-6 (40) = 0.000468","Full restraint forces that strain to zero, generating stress","sigma = 200,000(0.000468) = 93.6 MPa, compressive"],"formula":"Free strain = alpha * dT ;  if fully restrained, sigma = E alpha dT","note":"","pitfall":"Thermal stress is independent of length and cross-section. If your answer contains L or A, you have the wrong model. Heating a restrained bar produces COMPRESSION.","choices":[{"text":"0.0005","why":"That is the thermal STRAIN, a dimensionless number. Multiply by E to get stress."},{"text":"2.34","why":"You left out the temperature change."},{"text":"46.8","why":"There is no factor of one half in thermal stress."},{"text":"93.6","why":null}],"answer":3},{"id":"MECH-04","area":"Mechanics of Materials","topic":"Stresses and strains","prompt":"A solid circular shaft 50 mm in diameter transmits a torque of 3 kN*m. What is the maximum shear stress?","kind":"mc","diff":2,"units":"MPa","steps":["J = pi(50)^4 / 32 = 613,592 mm^4","r = 25 mm, T = 3,000,000 N*mm","tau = 3,000,000(25) / 613,592 = 122.2 MPa"],"formula":"tau = T r / J ;  J_solid = pi d^4 / 32","note":"","pitfall":"J = 2I for a circle. Grabbing pi d^4/64 out of the handbook by mistake halves your answer, and that half-value will be one of the options.","choices":[{"text":"0.1222","why":"Unit error: 3 kN*m is 3,000,000 N*mm, not 3,000. Working in N and mm is what makes the answer come out in MPa."},{"text":"4.889","why":"You left out the radius. tau = T r / J."},{"text":"122.2","why":null},{"text":"244.5","why":"You used I = pi d^4/64. For torsion use the POLAR moment J = pi d^4/32, which is twice I."}],"answer":2},{"id":"MECH-05","area":"Mechanics of Materials","topic":"Shear and moment diagrams","prompt":"A simply supported beam spans 8 m under a uniform load of 20 kN/m. What is the maximum bending moment?","kind":"mc","diff":1,"units":"kN*m","steps":["M_max = 20(8)^2 / 8 = 160 kN*m","V_max = 20(8) / 2 = 80 kN at each support","Maximum moment is at midspan, where the shear crosses zero"],"formula":"Simply supported, UDL: M_max = wL^2/8 at midspan, V_max = wL/2 at supports","note":"","pitfall":"Memorize the four standard cases cold: wL^2/8, PL/4, wL^2/2, PL. Deriving them under time pressure is wasted minutes.","choices":[{"text":"80","why":"That is the maximum SHEAR, in kN, which occurs at the supports."},{"text":"160","why":null},{"text":"320","why":"wL^2/4 corresponds to a central point load PL/4 with P = wL, not to a distributed load."},{"text":"640","why":"wL^2/2 is the CANTILEVER result. A simply supported beam is wL^2/8."}],"answer":1},{"id":"MECH-06","area":"Mechanics of Materials","topic":"Stresses and strains","prompt":"A rectangular beam 150 mm wide and 300 mm deep carries a bending moment of 90 kN*m. What is the maximum bending stress?","kind":"mc","diff":2,"units":"MPa","steps":["I = 150(300)^3 / 12 = 337,500,000 mm^4","c = 300/2 = 150 mm","sigma = 90e6(150) / 337,500,000 = 40 MPa"],"formula":"sigma = M c / I ;  I_rect = b h^3 / 12 ;  c = h/2","note":"","pitfall":"The section modulus S = I/c = bh^2/6 does this in one step: S = 150(300)^2/6 and sigma = M/S.","choices":[{"text":"40","why":null},{"text":"80","why":"You used the full depth instead of the distance to the extreme fibre, c = h/2."},{"text":"160","why":"You swapped b and h in I. The depth is cubed when bending about the strong axis."},{"text":"2,000","why":"Moment divided by area is not a bending stress."}],"answer":0},{"id":"MECH-07","area":"Mechanics of Materials","topic":"Combined stresses, principal stresses, and Mohr's circle","prompt":"At a point, sigma_x = 80 MPa, sigma_y = -20 MPa, and tau_xy = 30 MPa. What is the maximum principal stress?","kind":"mc","diff":3,"units":"MPa","steps":["sigma_avg = (80 - 20)/2 = 30 MPa (circle centre)","R = sqrt(((80 - (-20))/2)^2 + 30^2) = sqrt(50^2 + 30^2) = 58.31 MPa","sigma_1 = 30 + 58.31 = 88.31 MPa","sigma_2 = 30 - 58.31 = -28.31 MPa"],"formula":"sigma_avg = (sx + sy)/2 ;  R = sqrt( ((sx - sy)/2)^2 + txy^2 ) ;  sigma_1,2 = sigma_avg +/- R","note":"","pitfall":"Keep the sign on sigma_y. Using +20 instead of -20 moves the centre and shrinks the radius, and both wrong values appear as options.","choices":[{"text":"-28.31","why":"That is the MINIMUM principal stress, sigma_2."},{"text":"58.31","why":"That is the maximum in-plane shear stress, the radius of the circle."},{"text":"80","why":"sigma_x is not a principal stress unless tau_xy = 0."},{"text":"88.31","why":null}],"answer":3},{"id":"MECH-08","area":"Mechanics of Materials","topic":"Deformations","prompt":"A cantilever beam 3 m long carries a 10 kN point load at its free end. With E = 200 GPa and I = 80e6 mm^4, what is the tip deflection?","kind":"mc","diff":2,"units":"mm","steps":["L^3 = (3000)^3 = 2.7e10 mm^3","delta = 10,000(2.7e10) / (3 x 200,000 x 80e6)","delta = 5.625 mm"],"formula":"Cantilever, end point load: delta = P L^3 / (3 E I)","note":"","pitfall":"Deflection goes as L CUBED. Doubling the span multiplies tip deflection by eight, which is why span control dominates serviceability design.","choices":[{"text":"0.0028","why":"That expression is the tip ROTATION, in radians, not the deflection."},{"text":"0.3516","why":"PL^3/48EI is the SIMPLY SUPPORTED midspan case. A cantilever is PL^3/3EI, which is 16 times larger."},{"text":"2.109","why":"wL^4/8EI is the cantilever under a DISTRIBUTED load. This load is a point load."},{"text":"5.625","why":null}],"answer":3},{"id":"MECH-09","area":"Mechanics of Materials","topic":"Stresses and strains","prompt":"A 40 mm diameter bar is stressed to 150 MPa in tension. With E = 200 GPa and Poisson's ratio 0.30, what is the change in diameter?","kind":"mc","diff":3,"units":"mm","steps":["Axial strain = 150 / 200,000 = 0.00075","Lateral strain = -0.30(0.00075) = -0.000225","Change in diameter = -0.000225(40) = -0.009 mm (a decrease)"],"formula":"epsilon_axial = sigma/E ;  epsilon_lateral = -nu * epsilon_axial","note":"","pitfall":"Tension thins, compression fattens. Poisson's ratio for metals runs about 0.25 to 0.35; a value above 0.5 is physically impossible for an isotropic material.","choices":[{"text":"-0.1","why":"You divided by Poisson's ratio instead of multiplying."},{"text":"-0.009","why":null},{"text":"0.009","why":"The magnitude is right but the sign is not. A bar in TENSION gets thinner, so the diameter change is negative."},{"text":"0.03","why":"You applied the AXIAL strain to the diameter. The lateral strain is -nu times the axial strain."}],"answer":1},{"id":"MAT-01","area":"Materials","topic":"Mix design of concrete and asphalt","prompt":"Two concrete mixes use identical materials and the same cement content, but mix A has a water-cement ratio of 0.40 and mix B has 0.60. Which statement is correct?","kind":"mc","diff":1,"units":"","steps":["Lower w/c leaves fewer capillary voids after curing","Fewer voids gives higher strength AND lower permeability (better durability)","The cost is workability, which is recovered with admixtures rather than more water"],"formula":"Abrams' law: compressive strength decreases as the water-cement ratio increases.","note":"","pitfall":"Never add water on site to improve workability. It raises w/c and silently destroys the design strength.","choices":[{"text":"Mix A will have higher compressive strength and lower permeability than mix B","why":null},{"text":"Mix B will be stronger because the extra water improves hydration","why":"Hydration needs only about 0.22 to 0.25 by mass. Water beyond that leaves capillary pores behind when it evaporates."},{"text":"Both mixes will reach the same strength since the cement content is equal","why":"Strength tracks the water-cement RATIO, not cement content alone. This is Abrams' law."},{"text":"Mix A will be more workable and easier to place","why":"Backwards. Less water means lower slump and harder placement, which is the trade-off a low w/c mix buys you."}],"answer":0},{"id":"MAT-02","area":"Materials","topic":"Mix design of concrete and asphalt","prompt":"A concrete mix uses 350 kg of cement per cubic metre at a water-cement ratio of 0.45. How much water is required per cubic metre?","kind":"num","diff":1,"units":"kg/m^3","steps":["water = (w/c) x cement = 0.45(350)","water = 157.5 kg/m^3","Since 1 kg of water is 1 litre, that is also 157.5 L/m^3"],"formula":"w/c = mass of water / mass of cement","note":"","pitfall":"Divide and you get 778 kg/m^3, which is physically absurd for a cubic metre of concrete. Sanity-check the magnitude.","answer":157.5,"tol":0.01},{"id":"MAT-03","area":"Materials","topic":"Test methods and specifications","prompt":"A compacted asphalt specimen has a bulk specific gravity of 2.350 and a theoretical maximum specific gravity of 2.455. What is the air void content?","kind":"mc","diff":2,"units":"%","steps":["Gmb / Gmm = 2.350 / 2.455 = 0.9572","Va = (1 - 0.9572) x 100 = 4.277%","This sits inside the usual 3 to 5% design window for dense-graded mixes"],"formula":"Va = (1 - Gmb / Gmm) x 100","note":"","pitfall":"Gmm is the void-free maximum, so it must exceed Gmb. If your voids come out negative you have the two swapped.","choices":[{"text":"-4.47","why":"You inverted the ratio, giving a negative void content. Gmb is always the smaller of the two."},{"text":"4.28","why":null},{"text":"10.5","why":"You took the plain difference. The formula needs the ratio."},{"text":"95.72","why":"That is the percentage of the volume filled by material. Voids are the remainder."}],"answer":1},{"id":"MAT-04","area":"Materials","topic":"Test methods and specifications","prompt":"A 150 mm diameter concrete cylinder fails at a load of 530 kN. What is its compressive strength?","kind":"num","diff":1,"units":"MPa","steps":["A = pi(150)^2 / 4 = 17,671 mm^2","f'c = 530,000 / 17,671 = 29.99 MPa"],"formula":"f'c = P / A ;  A = pi d^2 / 4","note":"","pitfall":"A 150 x 300 mm cylinder is the standard specimen. A 100 x 200 mm cylinder of the same concrete tests slightly HIGHER because of the size effect.","answer":29.991864831539388,"tol":0.02},{"id":"MAT-05","area":"Materials","topic":"Physical and mechanical properties","prompt":"An aggregate sample weighs 505 g saturated surface-dry and 495 g oven-dry. What is the absorption?","kind":"mc","diff":2,"units":"%","steps":["Absorbed water = 505 - 495 = 10 g","Absorption = 10 / 495 x 100 = 2.02%"],"formula":"Absorption (%) = (SSD mass - oven-dry mass) / oven-dry mass x 100","note":"","pitfall":"Absorption uses oven-dry in the denominator; moisture CONTENT of a wet aggregate also uses oven-dry. Specific gravity is where the SSD basis shows up.","choices":[{"text":"1.98","why":"You divided by the SSD mass. Absorption is referenced to the OVEN-DRY mass."},{"text":"2.02","why":null},{"text":"10","why":"That is the mass of absorbed water in grams, not a percentage."},{"text":"98.02","why":"That is a mass ratio, not absorption."}],"answer":1},{"id":"MAT-06","area":"Materials","topic":"Physical and mechanical properties","prompt":"Which pairing of material and modulus of elasticity is approximately correct?","kind":"mc","diff":1,"units":"","steps":["Anchor on steel at 200 GPa / 29,000 ksi","Aluminum is about one third of steel; concrete about one eighth; wood about one twentieth","These ratios let you reject three options without a calculator"],"formula":"E_steel ~ 200 GPa ; E_concrete ~ 25 GPa (4700 sqrt(f'c) MPa) ; E_aluminum ~ 70 GPa ; E_wood ~ 11 GPa","note":"","pitfall":"Concrete's E depends on strength, roughly 4700*sqrt(f'c) in MPa. Steel's E does NOT change with grade; only its yield strength does.","choices":[{"text":"Structural steel, about 200 GPa (29,000 ksi)","why":null},{"text":"Structural steel, about 70 GPa (10,000 ksi)","why":"That is ALUMINUM. Steel is roughly three times stiffer."},{"text":"Normal-weight concrete, about 200 GPa","why":"Concrete is roughly 25 GPa, about one eighth of steel."},{"text":"Douglas fir lumber, about 70 GPa","why":"Wood parallel to grain is roughly 10 to 13 GPa. 70 GPa is aluminum."}],"answer":0},{"id":"FLU-01","area":"Fluid Mechanics","topic":"Fluid statics","prompt":"What is the gauge pressure at a depth of 6 m in fresh water?","kind":"mc","diff":1,"units":"kPa","steps":["p = 9.81 kN/m^3 x 6 m = 58.86 kPa","Equivalently 1000(9.81)(6) = 58,860 Pa"],"formula":"p = rho g h = gamma h   (gamma_water = 9.81 kN/m^3)","note":"","pitfall":"Roughly 10 kPa per metre of water is a useful field check. Also remember pressure depends only on DEPTH, never on the shape or volume of the container.","choices":[{"text":"6","why":"You omitted g. Density times depth is not a pressure."},{"text":"58.86","why":null},{"text":"160.2","why":"You reported ABSOLUTE pressure. The question asks for gauge, which excludes atmospheric."},{"text":"58,860","why":"That is the answer in PASCALS. The question asks for kPa, so divide by 1000."}],"answer":1},{"id":"FLU-02","area":"Fluid Mechanics","topic":"Fluid statics","prompt":"A vertical rectangular gate 2 m wide and 3 m tall has its top edge at the water surface. What is the total hydrostatic force on the gate?","kind":"mc","diff":2,"units":"kN","steps":["Centroid depth h_c = 3/2 = 1.5 m","Area A = 2(3) = 6 m^2","F = 9.81(1.5)(6) = 88.29 kN","The force acts at 2(3)/3 = 2 m below the surface, NOT at the centroid"],"formula":"F = gamma * h_centroid * A ;  centre of pressure at 2h/3 below the surface for a surface-piercing vertical rectangle","note":"","pitfall":"Force uses the CENTROID depth; its line of action is at the CENTRE OF PRESSURE, which is deeper. Two different depths in one problem.","choices":[{"text":"29.43","why":"You used width instead of area."},{"text":"88.29","why":null},{"text":"117.7","why":"You used the CENTRE OF PRESSURE depth (2 m). Force uses the CENTROID depth (1.5 m); the centre of pressure is only where it acts."},{"text":"176.6","why":"You used the full depth rather than the depth to the CENTROID of the gate, which is h/2."}],"answer":1},{"id":"FLU-03","area":"Fluid Mechanics","topic":"Flow measurement","prompt":"Water flows at 2 m/s through a 300 mm diameter pipe that reduces to 150 mm. What is the velocity in the smaller pipe?","kind":"mc","diff":2,"units":"m/s","steps":["Q = (pi/4)(0.3)^2(2) = 0.1414 m^3/s","A2 = (pi/4)(0.15)^2 = 0.0177 m^2","V2 = 0.1414 / 0.0177 = 8 m/s","Shortcut: halving the diameter quadruples the velocity"],"formula":"Q = A1 V1 = A2 V2 ;  V2 = V1 (D1/D2)^2","note":"","pitfall":"Halving a diameter quarters the area, so velocity goes up 4x, not 2x. This factor-of-two trap is on nearly every continuity question.","choices":[{"text":"0.5","why":"You inverted the ratio. A smaller pipe means a higher velocity."},{"text":"2","why":"Velocity cannot be unchanged when the area changes."},{"text":"4","why":"You scaled by the diameter ratio. Velocity scales with the ratio of diameters SQUARED, because area does."},{"text":"8","why":null}],"answer":3},{"id":"FLU-04","area":"Fluid Mechanics","topic":"Energy, impulse, and momentum of fluids","prompt":"A large open tank has a small orifice 5 m below the free water surface. Neglecting losses, what is the jet velocity?","kind":"num","diff":1,"units":"m/s","steps":["Bernoulli from surface to jet: all head converts to velocity head","v = sqrt(2(9.81)(5)) = sqrt(98.1)","v = 9.905 m/s"],"formula":"Torricelli: v = sqrt(2 g h)","note":"","pitfall":"This is Bernoulli with a free surface, so the answer is independent of the fluid's density. Water and oil exit at the same speed under the same head.","answer":9.904544411531507,"tol":0.02},{"id":"FLU-05","area":"Fluid Mechanics","topic":"Fluid properties","prompt":"Water at 20 degrees C (kinematic viscosity 1.0e-6 m^2/s) flows at 1.5 m/s in a 100 mm diameter pipe. What is the Reynolds number, and what is the flow regime?","kind":"mc","diff":2,"units":"","steps":["Re = 1.5(0.100) / 1.0e-6 = 150,000","150,000 is well above 4000, so the flow is turbulent","Nearly all civil water-conveyance flow is turbulent"],"formula":"Re = V D / nu = rho V D / mu. Laminar below ~2100, turbulent above ~4000.","note":"","pitfall":"Keep D in metres. Using millimetres inflates Re by 1000 and the inflated value will still read 'turbulent', hiding the error.","choices":[{"text":"150,000 - turbulent","why":null},{"text":"150,000 - laminar","why":"The number is right but the regime is not. Pipe flow is turbulent above about 4000 (laminar below about 2100)."},{"text":"150,000,000 - turbulent","why":"You used the diameter in millimetres. Re is dimensionless only if every term is in consistent SI units."},{"text":"150 - laminar","why":"You used dynamic viscosity in place of kinematic. Re = VD/nu uses kinematic viscosity."}],"answer":0},{"id":"FLU-06","area":"Fluid Mechanics","topic":"Energy, impulse, and momentum of fluids","prompt":"Water flows at 2 m/s through 100 m of 150 mm pipe with a friction factor of 0.02. What is the friction head loss?","kind":"mc","diff":2,"units":"m","steps":["L/D = 100 / 0.150 = 666.7","V^2/2g = 4 / 19.62 = 0.2039 m","hf = 0.02(666.7)(0.2039) = 2.718 m"],"formula":"Darcy-Weisbach: hf = f (L/D) (V^2 / 2g)","note":"","pitfall":"L and D must be in the SAME unit so that L/D is dimensionless. Mixing metres with millimetres here is the most common error.","choices":[{"text":"0.2039","why":"That is just the velocity head, with no friction multiplier."},{"text":"0.4077","why":"You left out the division by D."},{"text":"2.718","why":null},{"text":"5.437","why":"You omitted the 2 in the velocity head term. Velocity head is V^2/2g."}],"answer":2},{"id":"FLU-07","area":"Fluid Mechanics","topic":"Fluid statics","prompt":"A fully submerged object displaces 0.05 m^3 of fresh water. What is the buoyant force on it?","kind":"mc","diff":1,"units":"N","steps":["Displaced volume = 0.05 m^3","F = 1000(9.81)(0.05) = 490.5 N","Equivalently 9.81 kN/m^3 x 0.05 m^3 = 0.4905 kN"],"formula":"Archimedes: F_buoyant = gamma_fluid x V_displaced = rho g V","note":"","pitfall":"Buoyancy depends on the DISPLACED volume and the FLUID's density, never on the object's own density. Density only decides whether it floats.","choices":[{"text":"0.4905","why":"That is the answer in kN, but the question asks for newtons. Watch the requested unit."},{"text":"50","why":"You omitted g. Mass displaced is 50 kg; the FORCE is that times g."},{"text":"245.2","why":"You halved the displaced volume. The object is FULLY submerged, so it displaces its entire volume."},{"text":"490.5","why":null}],"answer":3},{"id":"FLU-08","area":"Fluid Mechanics","topic":"Energy, impulse, and momentum of fluids","prompt":"A water jet discharging 0.02 m^3/s at 15 m/s strikes a flat plate held normal to the jet and is deflected sideways. What force does the jet exert on the plate?","kind":"num","diff":2,"units":"N","steps":["Mass flow = rho Q = 1000(0.02) = 20 kg/s","The jet's normal momentum drops to zero, so F = mass flow x V","F = 20(15) = 300 N"],"formula":"F = rho Q (V_in - V_out). Normal flat plate: F = rho Q V","note":"","pitfall":"A plate takes rho*Q*V. A curved vane turning the jet a full 180 degrees takes TWICE that, because the momentum reverses instead of merely stopping.","answer":300.0,"tol":0.02},{"id":"SUR-01","area":"Surveying","topic":"Leveling","prompt":"A level is set up between a benchmark at elevation 100.000 m and a new point. The backsight on the benchmark reads 1.520 m and the foresight on the new point reads 2.870 m. What is the elevation of the new point?","kind":"mc","diff":1,"units":"m","steps":["HI = 100.000 + 1.520 = 101.52 m","Elevation = 101.52 - 2.870 = 98.65 m","The larger foresight reading confirms the new point is lower"],"formula":"HI = known elevation + BS ;  new elevation = HI - FS","note":"","pitfall":"Bigger rod reading means lower ground. Use that as an instant sanity check before you trust the arithmetic.","choices":[{"text":"98.65","why":null},{"text":"101.4","why":"You reversed backsight and foresight. The new point reads HIGHER on the rod, so it must be LOWER in elevation."},{"text":"101.5","why":"That is the height of instrument, not the point elevation."},{"text":"104.4","why":"Foresights are subtracted, not added."}],"answer":0},{"id":"SUR-02","area":"Surveying","topic":"Leveling","prompt":"A road rises 3.6 m over a horizontal distance of 240 m. What is the grade in percent?","kind":"num","diff":1,"units":"%","steps":["Grade = 3.6 / 240 = 0.015","x 100 = 1.5%"],"formula":"Grade (%) = (rise / horizontal run) x 100","note":"","pitfall":"Grade uses HORIZONTAL run, not slope distance. For grades under about 10% the difference is negligible, which is why the shortcut survives.","answer":1.5000000000000002,"tol":0.01},{"id":"SUR-03","area":"Surveying","topic":"Area computations","prompt":"A triangular parcel has corners at coordinates (100, 100), (200, 150), and (150, 250), in metres. What is its area?","kind":"num","diff":2,"units":"m^2","steps":["Cross products: 100(150) - 200(100) = -5,000","200(250) - 150(150) = +27,500","150(100) - 100(250) = -10,000","Sum = 12,500; area = |12,500| / 2 = 6,250 m^2"],"formula":"Area = (1/2) |sum( x_i * y_(i+1) - x_(i+1) * y_i )|   [coordinate method]","note":"","pitfall":"You must return to the FIRST point to close the loop. Omitting the last cross product is the standard mistake, and taking the absolute value at the end makes traverse direction irrelevant.","answer":6250.0,"tol":0.01},{"id":"SUR-04","area":"Surveying","topic":"Earthwork and volume computations","prompt":"Two cross sections 30 m apart have end areas of 25 m^2 and 40 m^2. Using the average end area method, what is the volume between them?","kind":"mc","diff":1,"units":"m^3","steps":["Average area = (25 + 40) / 2 = 32.5 m^2","V = 32.5(30) = 975 m^3"],"formula":"Average end area: V = L (A1 + A2) / 2","note":"","pitfall":"Average end area OVERESTIMATES when the section changes shape, which is why the prismoidal formula exists. It is the conservative, standard method for pay quantities.","choices":[{"text":"925","why":"That is the prismoidal formula with a measured middle area of 30 m^2. The question asked for the average end area method, and no middle section was given."},{"text":"948.7","why":"The geometric mean is not used in earthwork volumes."},{"text":"975","why":null},{"text":"1,950","why":"You forgot to average. Divide the sum of the end areas by 2."}],"answer":2},{"id":"SUR-05","area":"Surveying","topic":"Angles, distances, and trigonometry","prompt":"A line has an azimuth of 215 degrees measured clockwise from north. What is its bearing?","kind":"mc","diff":2,"units":"","steps":["215 degrees falls between 180 and 270, so the line heads southwest","Bearing angle = 215 - 180 = 35 degrees","Bearing = S 35 W"],"formula":"Quadrant 1 (0-90): N az E | Q2 (90-180): S (180 - az) E | Q3 (180-270): S (az - 180) W | Q4 (270-360): N (360 - az) W","note":"","pitfall":"Sketch the compass and mark the quadrant before converting. Every wrong option here is a plausible arithmetic result with the wrong quadrant.","choices":[{"text":"S 35 W","why":null},{"text":"N 35 W","why":"Azimuth 215 is in the THIRD quadrant (180 to 270), which is southwest, not northwest."},{"text":"S 55 W","why":"You subtracted from 270 instead of 180. For the third quadrant, bearing angle = azimuth - 180."},{"text":"S 35 E","why":"Correct angle, wrong side. East bearings come from the second quadrant (90 to 180), not the third."}],"answer":0},{"id":"SUR-06","area":"Surveying","topic":"Angles, distances, and trigonometry","prompt":"A total station measures a slope distance of 150.00 m with a vertical angle of -4 degrees 30 minutes. What is the horizontal distance?","kind":"num","diff":2,"units":"m","steps":["4 degrees 30 minutes = 4.5 degrees","H = 150.00 cos(4.5) = 149.538 m","The elevation difference would be 150 sin(-4.5) = 11.769 m"],"formula":"Horizontal = S cos(vertical angle) ;  Vertical = S sin(vertical angle)","note":"","pitfall":"If the instrument reports a ZENITH angle instead (measured from straight up), horizontal distance uses SINE. Confirm which convention the instrument uses.","answer":149.5376000599692,"tol":0.005},{"id":"SUR-07","area":"Surveying","topic":"Coordinate systems","prompt":"A closed traverse with a perimeter of 800 m has a latitude misclosure of +0.08 m and a departure misclosure of -0.06 m. What is the precision of closure?","kind":"mc","diff":3,"units":"","steps":["Misclosure = sqrt(0.08^2 + 0.06^2) = sqrt(0.0064 + 0.0036) = 0.1 m","Precision = 800 / 0.1 = 8,000","Reported as 1:8,000"],"formula":"Linear misclosure = sqrt(sum_lat^2 + sum_dep^2) ; precision = perimeter / misclosure","note":"","pitfall":"A 3-4-5 triangle again (0.06, 0.08, 0.10). Precision is always written as 1 : a large number, so a small ratio means you inverted it.","choices":[{"text":"1:8,000","why":null},{"text":"1:5,714","why":"You added the misclosures directly. They are perpendicular components, so combine them with Pythagoras."},{"text":"1:0.0001","why":"The ratio is inverted. Precision is expressed as 1 over a large number."},{"text":"1:10,000","why":"You used only the latitude misclosure and ignored the departure."}],"answer":0},{"id":"SUR-08","area":"Surveying","topic":"Angles, distances, and trigonometry","prompt":"A simple horizontal curve has a radius of 250 m and a central angle of 36 degrees. What is the curve length?","kind":"mc","diff":2,"units":"m","steps":["delta = 36 degrees = 0.6283 radians","L = 250(0.6283) = 157.1 m","For comparison T = 250 tan(18) = 81.23 m and LC = 154.5 m"],"formula":"L = R * delta(radians) = pi R delta / 180 ;  T = R tan(delta/2) ;  LC = 2R sin(delta/2)","note":"","pitfall":"Arc length needs RADIANS. Using 36 directly gives 9000 m, which is obviously wrong but easy to write down in a hurry.","choices":[{"text":"81.23","why":"That is the TANGENT distance, T = R tan(delta/2)."},{"text":"154.5","why":"That is the LONG CHORD, which is slightly shorter than the arc."},{"text":"157.1","why":null},{"text":"9,000","why":"You used degrees directly. Convert the central angle to radians first, or use pi*R*delta/180."}],"answer":2},{"id":"WAT-01","area":"Water Resources and Environmental Engineering","topic":"Basic hydrology","prompt":"Using the rational method in SI units, find the peak runoff from a 5 hectare catchment with a runoff coefficient of 0.60 and a rainfall intensity of 50 mm/hr.","kind":"mc","diff":2,"units":"m^3/s","steps":["Q = 0.60(50)(5) / 360","Q = 150 / 360 = 0.4167 m^3/s"],"formula":"SI: Q(m^3/s) = C i A / 360, with i in mm/hr and A in hectares.\nUS: Q(cfs) = C i A, with i in in/hr and A in acres.","note":"","pitfall":"The US form needs NO conversion constant because 1 acre-inch per hour is almost exactly 1 cfs. The SI form needs 360. Know which units you are in.","choices":[{"text":"0.0417","why":"The SI constant is 360, not 3600."},{"text":"0.4167","why":null},{"text":"0.6944","why":"You dropped the runoff coefficient. Not all rainfall becomes runoff."},{"text":"150","why":"You omitted the 360 conversion. C*i*A with mm/hr and hectares is not m^3/s."}],"answer":1},{"id":"WAT-02","area":"Water Resources and Environmental Engineering","topic":"Basic hydraulics","prompt":"A rectangular channel 3 m wide flows 1.2 m deep. Manning's n is 0.015 and the bed slope is 0.002. What is the discharge?","kind":"mc","diff":3,"units":"m^3/s","steps":["A = 3(1.2) = 3.6 m^2","P = 3 + 2(1.2) = 5.4 m, so R = 3.6 / 5.4 = 0.6667 m","V = (1/0.015)(0.6667)^(2/3)(0.002)^(1/2) = 2.275 m/s","Q = 3.6(2.275) = 8.191 m^3/s"],"formula":"SI: V = (1/n) R^(2/3) S^(1/2) ;  US: V = (1.486/n) R^(2/3) S^(1/2) ;  R = A / P","note":"","pitfall":"The 1.486 (often written 1.49) coefficient belongs ONLY to US customary units. Using it in SI inflates your answer by 49%.","choices":[{"text":"0.3663","why":"You forgot the square root on the slope."},{"text":"8.191","why":null},{"text":"9.685","why":"Your wetted perimeter is wrong. An open rectangular channel wets the bed plus BOTH sides: P = b + 2y."},{"text":"12.12","why":"You used depth as the hydraulic radius. R = A/P, which is smaller than y here."}],"answer":1},{"id":"WAT-03","area":"Water Resources and Environmental Engineering","topic":"Pumps","prompt":"A pump delivers 0.10 m^3/s against a total head of 25 m at 75% efficiency. What input power is required?","kind":"mc","diff":2,"units":"kW","steps":["Water power = 9.81(0.10)(25) = 24.53 kW","Input power = 24.53 / 0.75 = 32.7 kW"],"formula":"Water power = gamma Q H ;  Input power = gamma Q H / efficiency","note":"","pitfall":"Efficiency always makes the required input BIGGER. If your answer shrank, you multiplied where you should have divided.","choices":[{"text":"3.333","why":"The specific weight of water is missing."},{"text":"18.39","why":"You multiplied by efficiency. Input power is always LARGER than output power."},{"text":"24.53","why":"That is the WATER power (useful output). Divide by efficiency to get the required input."},{"text":"32.7","why":null}],"answer":3},{"id":"WAT-04","area":"Water Resources and Environmental Engineering","topic":"Stormwater","prompt":"A detention basin receives a steady inflow of 1.2 m^3/s while releasing 0.5 m^3/s for 30 minutes. What storage volume accumulates?","kind":"num","diff":1,"units":"m^3","steps":["Net inflow = 1.2 - 0.5 = 0.7 m^3/s","Duration = 30 min = 1,800 s","Volume = 0.7(1,800) = 1,260 m^3"],"formula":"Storage = (inflow - outflow) x time   [continuity / routing]","note":"","pitfall":"Convert minutes to seconds before multiplying by a m^3/s flow. Forgetting the 60 is a factor-of-60 error, not a rounding error.","answer":1260.0,"tol":0.01},{"id":"WAT-05","area":"Water Resources and Environmental Engineering","topic":"Groundwater","prompt":"An aquifer has a hydraulic conductivity of 2.5e-4 m/s and a hydraulic gradient of 0.015. For a cross-sectional area of 200 m^2, what is the discharge?","kind":"mc","diff":2,"units":"m^3/s","steps":["v_Darcy = 2.5e-4(0.015) = 0.00000375 m/s","Q = 0.00000375(200) = 0.00075 m^3/s = 0.75 L/s","For reference the seepage velocity is 0.00000375 / 0.30 = 0.0000125 m/s"],"formula":"Darcy: Q = k i A ;  v_Darcy = k i ;  v_seepage = k i / n","note":"","pitfall":"Darcy velocity is fictitious (flow spread over the whole area). Actual particle travel uses SEEPAGE velocity = v/n, which is always larger.","choices":[{"text":"0","why":"Area multiplies, it does not divide."},{"text":"0.0008","why":null},{"text":"0.0025","why":"You used the SEEPAGE velocity. Darcy's law uses the bulk (discharge) velocity for Q."},{"text":"0.05","why":"You omitted the gradient. Flow is driven by the head gradient."}],"answer":1},{"id":"WAT-06","area":"Water Resources and Environmental Engineering","topic":"Water and wastewater treatment","prompt":"A treatment tank has a volume of 500 m^3 and receives 2000 m^3/day. What is the hydraulic residence time in hours?","kind":"num","diff":1,"units":"hours","steps":["HRT = 500 / 2000 = 0.25 day","x 24 = 6 hours"],"formula":"HRT = Volume / Flow rate","note":"","pitfall":"Check the unit the question wants. The same tank is 0.25 day, 6 hours, or 360 minutes, and at least two of those will be on the answer list.","answer":6.0,"tol":0.01},{"id":"WAT-07","area":"Water Resources and Environmental Engineering","topic":"Water quality","prompt":"A wastewater plant reduces BOD from 220 mg/L to 20 mg/L. What is the removal efficiency?","kind":"mc","diff":1,"units":"%","steps":["Removed = 220 - 20 = 200 mg/L","Efficiency = 200 / 220 x 100 = 90.91%"],"formula":"Removal (%) = (C_in - C_out) / C_in x 100","note":"","pitfall":"Secondary treatment is typically specified around 85 to 95% BOD removal. An answer near 1000% means you used the effluent as the reference.","choices":[{"text":"9.1","why":"That is the fraction REMAINING, not the fraction removed."},{"text":"90.9","why":null},{"text":"200","why":"That is the concentration removed in mg/L, not a percentage."},{"text":"1,000","why":"You divided by the EFFLUENT concentration. Efficiency is referenced to the influent."}],"answer":1},{"id":"WAT-08","area":"Water Resources and Environmental Engineering","topic":"Water and wastewater treatment","prompt":"A plant treating 4000 m^3/day applies a chlorine dose of 2.5 mg/L. What mass of chlorine is needed per day?","kind":"num","diff":2,"units":"kg/day","steps":["1 mg/L in 1 m^3 is 1 gram, since 1 m^3 = 1000 L","Mass = 4000 x 2.5 = 10,000 g/day","= 10 kg/day"],"formula":"Mass (kg/d) = Q(m^3/d) x dose(mg/L) / 1000","note":"","pitfall":"Memorize the SI shortcut: Q(m^3/d) x C(mg/L) = grams/day. In US units it is lb/day = Q(MGD) x C(mg/L) x 8.34.","answer":10.0,"tol":0.01},{"id":"WAT-09","area":"Water Resources and Environmental Engineering","topic":"Water quality","prompt":"Water contains 80 mg/L of calcium ion (Ca2+, atomic mass 40.08). Expressed as CaCO3 (molar mass 100.09), what is the hardness?","kind":"mc","diff":3,"units":"mg/L as CaCO3","steps":["Equivalent weight of Ca2+ = 40.08 / 2 = 20.04","Equivalent weight of CaCO3 = 100.09 / 2 = 50.04","Hardness = 80 x 50.04 / 20.04 = 200 mg/L as CaCO3"],"formula":"mg/L as CaCO3 = mg/L of ion x (equivalent weight of CaCO3 / equivalent weight of the ion). Equivalent weight = molar mass / charge.","note":"","pitfall":"Always divide molar mass by CHARGE to get equivalent weight. For Ca2+ and CaCO3 both charges are 2 so it cancels, but for Na+ it does not.","choices":[{"text":"32","why":"You inverted the equivalent-weight ratio. Converting to CaCO3 always INCREASES the number, because CaCO3 is heavier per equivalent."},{"text":"80","why":"No conversion was applied."},{"text":"100","why":"You used calcium's full molar mass instead of its equivalent weight. Divide by the charge of 2 first."},{"text":"200","why":null}],"answer":3},{"id":"WAT-10","area":"Water Resources and Environmental Engineering","topic":"Flow measurement","prompt":"A sharp-crested rectangular weir 2.0 m long carries a head of 0.30 m. Using Q = 1.84 L H^1.5 (SI), what is the discharge?","kind":"mc","diff":2,"units":"m^3/s","steps":["H^1.5 = 0.30^1.5 = 0.1643","Q = 1.84(2.0)(0.1643) = 0.6047 m^3/s"],"formula":"Rectangular weir: Q = 1.84 L H^1.5 ;  V-notch (90 deg): Q = 1.38 H^2.5   [SI]","note":"","pitfall":"Exponent 1.5 for rectangular, 2.5 for V-notch. A V-notch is far more sensitive at low flow, which is why it is used for small discharges.","choices":[{"text":"0.1814","why":"The 2.5 exponent belongs to a TRIANGULAR (V-notch) weir, not a rectangular one."},{"text":"0.3023","why":"The weir length is missing."},{"text":"0.6047","why":null},{"text":"1.104","why":"The head is raised to the 1.5 power, not the first power."}],"answer":2},{"id":"WAT-11","area":"Water Resources and Environmental Engineering","topic":"Basic hydraulics","prompt":"A rectangular channel 3 m wide carries 8 m^3/s. What is the critical depth?","kind":"num","diff":3,"units":"m","steps":["Unit discharge q = 8 / 3 = 2.667 m^2/s","q^2 / g = 7.111 / 9.81 = 0.7249","y_c = (0.7249)^(1/3) = 0.8983 m"],"formula":"Rectangular channel: y_c = (q^2 / g)^(1/3), where q = Q / b","note":"","pitfall":"Critical depth depends ONLY on discharge and width, never on slope or roughness. If n or S appears in your work, you are computing NORMAL depth instead.","answer":0.8983029358549409,"tol":0.02},{"id":"WAT-12","area":"Water Resources and Environmental Engineering","topic":"Basic hydraulics","prompt":"In an open channel the Froude number is computed as 0.65. What is the flow regime, and what does it imply?","kind":"mc","diff":2,"units":"","steps":["Fr = 0.65 < 1, so the flow is subcritical","Subcritical flow is deep and slow relative to critical","Disturbances travel upstream, so the CONTROL is downstream - this is why a culvert or weir raises the water surface upstream of itself"],"formula":"Fr = V / sqrt(g y). Fr < 1 subcritical, Fr = 1 critical, Fr > 1 supercritical.","note":"","pitfall":"A hydraulic jump happens only going from supercritical to subcritical. The reverse transition is smooth and gradual.","choices":[{"text":"Subcritical - flow is deep and slow, and downstream conditions control the water surface","why":null},{"text":"Supercritical - flow is shallow and fast, and upstream conditions control","why":"Supercritical requires Fr greater than 1. At 0.65 the flow is subcritical."},{"text":"Critical - the specific energy is at its minimum","why":"Critical flow is Fr exactly equal to 1."},{"text":"Subcritical - but upstream conditions control the water surface","why":"The regime is right and the control is wrong. Subcritical flow is controlled from DOWNSTREAM, which is why backwater curves propagate upstream."}],"answer":0},{"id":"STR-01","area":"Structural Engineering","topic":"Structural determinacy and stability analysis","prompt":"A planar truss has 11 members, 7 joints, and 3 reaction components. Is it statically determinate?","kind":"mc","diff":2,"units":"","steps":["m + r = 11 + 3 = 14","2j = 2(7) = 14","14 = 14, so the truss is statically determinate"],"formula":"Planar truss: m + r = 2j determinate ; m + r > 2j indeterminate ; m + r < 2j unstable","note":"","pitfall":"Equality is necessary but NOT sufficient. A truss can satisfy m + r = 2j and still be unstable if the members are badly arranged (geometric instability).","choices":[{"text":"Determinate, because m + r = 2j","why":null},{"text":"Indeterminate to the first degree","why":"Check the arithmetic: 11 + 3 = 14 and 2(7) = 14. They are equal, so there is no redundancy."},{"text":"Unstable, because it has too few members","why":"Too few members would give m + r < 2j. Here they are equal."},{"text":"Indeterminate to the third degree","why":"You may have counted the 3 reactions as redundants. Reactions belong on the LEFT side of m + r = 2j."}],"answer":0},{"id":"STR-02","area":"Structural Engineering","topic":"Column analysis","prompt":"A pinned-pinned steel column is 4 m long with E = 200 GPa and I = 20e6 mm^4. What is the Euler buckling load?","kind":"mc","diff":2,"units":"kN","steps":["(KL)^2 = (1.0 x 4000)^2 = 1.6e7 mm^2","P_cr = pi^2(200,000)(20e6) / 1.6e7","P_cr = 2,467,401 N = 2,467 kN"],"formula":"P_cr = pi^2 E I / (K L)^2.  K: pinned-pinned 1.0, fixed-fixed 0.5, fixed-pinned 0.7, fixed-free 2.0","note":"","pitfall":"Capacity goes as 1/K^2. Fixing both ends QUADRUPLES the buckling load; a flagpole column has only one quarter of the pinned capacity.","choices":[{"text":"616.9","why":"That uses K = 2, the fixed-free (flagpole) case, which is the weakest."},{"text":"785.4","why":"pi is SQUARED in the Euler formula."},{"text":"2,467","why":null},{"text":"9,870","why":"That is the FIXED-FIXED case with K = 0.5, which is four times stronger. A pinned column has K = 1.0."}],"answer":2},{"id":"STR-03","area":"Structural Engineering","topic":"Loads, load combinations, and load paths","prompt":"An interior column in a regular grid has bays of 6 m and 8 m on all sides. For a uniform floor load of 10 kPa, what axial load does one floor deliver to the column?","kind":"num","diff":1,"units":"kN","steps":["The column takes half of each adjacent bay, so the tributary area is 6 x 8 = 48 m^2","P = 48 x 10 kPa = 480 kN"],"formula":"Tributary area for an interior column = (half-span each way) x (half-span each way) = full bay x full bay","note":"","pitfall":"An INTERIOR column's tributary area equals one full bay. An EDGE column gets half that and a CORNER column a quarter. Identify the position first.","answer":480.0,"tol":0.01},{"id":"STR-04","area":"Structural Engineering","topic":"Loads, load combinations, and load paths","prompt":"A beam carries a dead load of 30 kN/m and a live load of 45 kN/m. Using LRFD combinations 1.4D and 1.2D + 1.6L, what is the governing factored load?","kind":"mc","diff":1,"units":"kN/m","steps":["1.4D = 1.4(30) = 42 kN/m","1.2D + 1.6L = 1.2(30) + 1.6(45) = 36 + 72 = 108 kN/m","The larger governs: 108 kN/m"],"formula":"LRFD: U = 1.4D  or  U = 1.2D + 1.6L (take the larger)","note":"","pitfall":"Always evaluate BOTH and take the larger. 1.4D governs only when L is less than about one eighth of D, which is rare in buildings.","choices":[{"text":"42","why":"1.4D alone gives 42 kN/m, which is smaller. 1.4D only governs when the live load is very small relative to dead load."},{"text":"75","why":"That is the unfactored service load. LRFD requires load factors."},{"text":"81","why":"The live load factor in the primary gravity combination is 1.6, not 1.0."},{"text":"108","why":null}],"answer":3},{"id":"STR-05","area":"Structural Engineering","topic":"Design of steel components","prompt":"A steel beam must resist a factored moment of 250 kN*m. With Fy = 345 MPa and a flexural resistance factor of 0.90, what plastic section modulus Z is required for a compact section?","kind":"num","diff":2,"units":"mm^3","steps":["Mu = 250 kN*m = 250e6 N*mm","Z = 250e6 / (0.90 x 345)","Z = 805,153 mm^3, about 805 x 10^3 mm^3"],"formula":"phi Mn = phi Fy Z  (compact, fully braced) -> Z_req = Mu / (phi Fy)","note":"","pitfall":"Z (plastic) is for compact sections reaching the plastic moment; S (elastic) applies when the section yields only at the extreme fibre. Z is roughly 10 to 15% larger than S for rolled shapes.","answer":805152.9790660226,"tol":0.02},{"id":"STR-06","area":"Structural Engineering","topic":"Design of reinforced concrete components","prompt":"A reinforced concrete beam resists a factored moment of 200 kN*m with d = 400 mm and fy = 420 MPa. Using an assumed internal lever arm of 0.9d and phi = 0.90, estimate the required tension steel area.","kind":"mc","diff":3,"units":"mm^2","steps":["Lever arm = 0.9(400) = 360 mm","As = 200e6 / (0.90 x 420 x 360)","As = 1,470 mm^2","Then verify by computing a = As fy / (0.85 f'c b) and iterating once"],"formula":"Mn = As fy (d - a/2) ;  with the lever arm approximated as 0.9d, As = Mu / (phi fy 0.9d)","note":"","pitfall":"0.9d is a FIRST ESTIMATE only. On the real exam, if f'c and b are given, compute a = As*fy/(0.85*f'c*b) and re-solve. One iteration is usually enough.","choices":[{"text":"735","why":"No factor of 2 belongs here."},{"text":"1,190","why":"You omitted BOTH phi and the lever-arm reduction. Each one alone increases the required steel."},{"text":"1,323","why":"You used the full depth d as the lever arm. The compression resultant sits inside the section, so the lever arm is less than d."},{"text":"1,470","why":null}],"answer":3},{"id":"STR-07","area":"Structural Engineering","topic":"Deflection of statically determinant beams","prompt":"A simply supported beam spans 6 m under a uniform load of 15 kN/m. With E = 200 GPa and I = 200e6 mm^4, what is the midspan deflection?","kind":"mc","diff":2,"units":"mm","steps":["w = 15 kN/m = 15 N/mm, L = 6000 mm","L^4 = 1.296e15 mm^4","delta = 5(15)(1.296e15) / (384 x 200,000 x 200e6) = 6.328 mm","Span/deflection = 6000/6.328 = 948, comfortably better than a typical L/360 limit"],"formula":"Simply supported, UDL: delta_max = 5 w L^4 / (384 E I)","note":"","pitfall":"Deflection limits are span ratios (L/240, L/360, L/480). Convert your answer to L/x and sanity-check it against the limit.","choices":[{"text":"0.0011","why":"The span is raised to the FOURTH power for a distributed load, not the third."},{"text":"1.266","why":"The numerator coefficient is 5, not 1."},{"text":"6.328","why":null},{"text":"60.75","why":"wL^4/8EI is the CANTILEVER tip deflection, which is far larger."}],"answer":2},{"id":"STR-08","area":"Structural Engineering","topic":"Elementary statically indeterminate structures","prompt":"A beam with BOTH ends fixed spans 9 m under a uniform load of 24 kN/m. What is the magnitude of the moment at each support?","kind":"mc","diff":2,"units":"kN*m","steps":["wL^2 = 24(81) = 1,944 kN*m","M_support = 1,944 / 12 = 162 kN*m (negative, tension on top)","M_midspan = 1,944 / 24 = 81 kN*m","Note the total 'swing' wL^2/12 + wL^2/24 = wL^2/8 matches the simply supported value"],"formula":"Fixed-fixed UDL: M_support = wL^2/12, M_midspan = wL^2/24.  Propped cantilever UDL: M_fixed = wL^2/8.","note":"","pitfall":"Learn the family: /8 simply supported, /12 and /24 fixed-fixed, /8 at the fixed end of a propped cantilever. The sum of support and midspan moments always returns wL^2/8.","choices":[{"text":"81","why":"That is the MIDSPAN moment, wL^2/24, which is half the support moment."},{"text":"162","why":null},{"text":"243","why":"wL^2/8 is the simply supported midspan moment. Fixing the ends redistributes moment into the supports."},{"text":"972","why":"wL^2/2 is a cantilever."}],"answer":1},{"id":"STR-09","area":"Structural Engineering","topic":"Design of steel components","prompt":"A steel tension member has a gross area of 2400 mm^2 and Fy = 250 MPa. What is the design tensile strength for yielding on the gross section?","kind":"mc","diff":2,"units":"kN","steps":["phi Pn = 0.90(250)(2400) = 540,000 N","= 540 kN","The net-section rupture check with Fu and Ae must also be made; the governing strength is the lesser"],"formula":"Gross yielding: phi Pn = 0.90 Fy Ag.  Net rupture: phi Pn = 0.75 Fu Ae.  Take the smaller.","note":"","pitfall":"Two limit states, two phi factors, two areas: 0.90/Fy/Ag for yielding and 0.75/Fu/Ae for rupture. Mixing them up is the classic tension-member error.","choices":[{"text":"270","why":"Arithmetic slip of a factor of 2."},{"text":"450","why":"0.75 is the factor for RUPTURE on the net section, paired with Fu, not Fy."},{"text":"540","why":null},{"text":"600","why":"You omitted the resistance factor of 0.90 for gross yielding."}],"answer":2},{"id":"STR-10","area":"Structural Engineering","topic":"Analysis of statically determinant beams","prompt":"A simply supported beam spans 10 m. A single 40 kN load can be positioned anywhere along the span. What is the largest bending moment it can produce?","kind":"mc","diff":2,"units":"kN*m","steps":["For a point load at distance a from the left, M = P a (L - a) / L","This is maximized at a = L/2, giving M = P L / 4","M_max = 40(10) / 4 = 100 kN*m"],"formula":"Moving single point load on a simple span: M_max = P L / 4, with the load at midspan.","note":"","pitfall":"For a MOVING load the critical position is part of the answer. Maximum moment occurs at midspan; maximum SHEAR occurs with the load right next to a support.","choices":[{"text":"50","why":"PL/8 is not a standard case. For a central point load it is PL/4."},{"text":"100","why":null},{"text":"200","why":"PL/2 would require a cantilever."},{"text":"400","why":"PL is the cantilever moment with the load at the tip."}],"answer":1},{"id":"STR-11","area":"Structural Engineering","topic":"Analysis of statically determinant beams","prompt":"In a simply supported beam, where does the maximum bending moment occur for any transverse loading?","kind":"mc","diff":2,"units":"","steps":["Moment is the integral of shear, so M peaks where V = 0","That point coincides with midspan only when the loading is symmetric","Practical method: draw V, find where it crosses zero, then take the area under V up to that point"],"formula":"dM/dx = V. Moment is stationary where shear is zero; M(x) = integral of V dx = area under the shear diagram.","note":"","pitfall":"A point load makes shear JUMP through zero without passing through it smoothly. In that case the maximum moment sits right at the load.","choices":[{"text":"Where the shear diagram crosses zero","why":null},{"text":"Always exactly at midspan","why":"True only for symmetric loading. An off-centre load moves the maximum."},{"text":"At the supports, where the reactions are largest","why":"A simply supported beam has ZERO moment at its supports by definition."},{"text":"Where the load intensity is greatest","why":"Load intensity drives the shape of the shear curve, not the location of maximum moment."}],"answer":0},{"id":"STR-12","area":"Structural Engineering","topic":"Column analysis","prompt":"Two identical steel columns differ only in end conditions: column A is pinned at both ends, column B is fixed at both ends. How does B's elastic buckling capacity compare?","kind":"mc","diff":2,"units":"","steps":["Pinned-pinned: K = 1.0 ;  fixed-fixed: K = 0.5","Ratio = (1.0 / 0.5)^2 = 4","Column B buckles at four times the load of column A"],"formula":"P_cr = pi^2 E I / (K L)^2, so P_cr is proportional to 1/K^2","note":"","pitfall":"Real connections are never perfectly fixed. Codes give recommended design K values that are more conservative than the theoretical 0.5.","choices":[{"text":"B carries four times the load, because K drops from 1.0 to 0.5 and capacity varies as 1/K^2","why":null},{"text":"B carries twice the load, since K is halved","why":"Capacity depends on K SQUARED, so halving K multiplies capacity by four, not two."},{"text":"They are identical, because Euler buckling depends only on E and I","why":"The effective length (KL) is squarely in the denominator. End restraint matters enormously."},{"text":"B carries half the load, because fixed ends add restraint moments","why":"Restraint increases capacity. Fixing the ends shortens the buckled shape and stiffens the column."}],"answer":0},{"id":"GEO-01","area":"Geotechnical Engineering","topic":"Phase relations","prompt":"A soil has a porosity of 0.40. What is its void ratio?","kind":"mc","diff":2,"units":"","steps":["e = 0.40 / (1 - 0.40) = 0.40 / 0.60","e = 0.6667"],"formula":"e = n / (1 - n) ;  n = e / (1 + e).  n is voids/total; e is voids/solids.","note":"","pitfall":"Porosity is always less than 1; void ratio can exceed 1 for very loose soils. If your 'porosity' came out above 1, you computed e.","choices":[{"text":"0.4","why":"Porosity and void ratio are different: porosity references TOTAL volume, void ratio references SOLIDS volume."},{"text":"0.6","why":"That is the volume fraction of solids, not the void ratio."},{"text":"0.6667","why":null},{"text":"1.5","why":"You inverted the relation. Void ratio = n/(1-n)."}],"answer":2},{"id":"GEO-02","area":"Geotechnical Engineering","topic":"Index properties and soil classifications","prompt":"A saturated soil has a specific gravity of solids of 2.68 and a void ratio of 0.65. What is its saturated unit weight?","kind":"mc","diff":2,"units":"kN/m^3","steps":["gamma_sat = (2.68 + 0.65)(9.81) / (1 + 0.65)","= 3.33(9.81) / 1.65","= 19.8 kN/m^3","For reference gamma_dry = 15.93 and gamma' = 9.988 kN/m^3"],"formula":"gamma_dry = Gs*gamma_w/(1+e) ;  gamma_sat = (Gs+e)*gamma_w/(1+e) ;  gamma' = gamma_sat - gamma_w","note":"","pitfall":"Most natural soils fall between 15 and 22 kN/m^3. An answer of 26 kN/m^3 is the mineral unit weight, meaning you forgot the voids.","choices":[{"text":"9.988","why":"That is the BUOYANT (effective) unit weight, used below the water table."},{"text":"15.93","why":"That is the DRY unit weight. Saturated includes the weight of water filling the voids."},{"text":"19.8","why":null},{"text":"26.29","why":"That is the unit weight of the solid mineral alone, with no voids."}],"answer":2},{"id":"GEO-03","area":"Geotechnical Engineering","topic":"Laboratory and field tests","prompt":"A soil sample weighs 2150 g wet and 1800 g after oven drying. What is the water content?","kind":"num","diff":1,"units":"%","steps":["Water mass = 2150 - 1800 = 350 g","w = 350 / 1800 x 100 = 19.44%"],"formula":"w (%) = (mass of water / mass of DRY solids) x 100","note":"","pitfall":"The denominator is DRY mass, never wet mass. Dividing by 2150 gives 16.3% and will be an option. Water content can legitimately exceed 100% in organic soils and soft clays.","answer":19.444444444444446,"tol":0.01},{"id":"GEO-04","area":"Geotechnical Engineering","topic":"Effective stress","prompt":"A profile has 3 m of sand (unit weight 18 kN/m^3) above the water table, over 4 m of saturated sand (20 kN/m^3). What is the effective vertical stress at a depth of 7 m?","kind":"mc","diff":2,"units":"kPa","steps":["Total stress = 3(18) + 4(20) = 54 + 80 = 134 kPa","Pore pressure = 4(9.81) = 39.24 kPa","sigma' = 134 - 39.24 = 94.76 kPa"],"formula":"sigma = sum(gamma_i h_i) ;  u = gamma_w h_w ;  sigma' = sigma - u","note":"","pitfall":"Pore pressure is measured from the WATER TABLE down, not from the ground surface. Using 7 m of water here is the standard error.","choices":[{"text":"39.24","why":"That is the pore water pressure alone."},{"text":"94.76","why":null},{"text":"134","why":"That is TOTAL stress. Subtract the pore water pressure to get effective stress."},{"text":"173.2","why":"Pore pressure is subtracted, not added. Water carries part of the load, relieving the grains."}],"answer":1},{"id":"GEO-05","area":"Geotechnical Engineering","topic":"Stability of retaining structures","prompt":"A 5 m high retaining wall holds cohesionless backfill with a friction angle of 30 degrees and a unit weight of 18 kN/m^3. What is the total active thrust per metre of wall?","kind":"mc","diff":3,"units":"kN/m","steps":["Ka = tan^2(45 - 15) = tan^2(30) = 0.3333","Pa = 0.5(0.3333)(18)(5^2) = 75 kN/m","The resultant acts at 5/3 = 1.667 m above the base"],"formula":"Ka = tan^2(45 - phi/2) ;  Kp = tan^2(45 + phi/2) ;  Pa = (1/2) Ka gamma H^2, acting at H/3 above the base","note":"","pitfall":"For phi = 30, Ka = 1/3 and Kp = 3 exactly. Memorize that pair as an instant check: Kp = 1/Ka.","choices":[{"text":"75","why":null},{"text":"150","why":"You omitted the one half. The pressure diagram is triangular."},{"text":"225","why":"The earth pressure coefficient is missing."},{"text":"675","why":"You used the PASSIVE coefficient. Kp = 3 and Ka = 1/3 for phi = 30, so this is nine times too large."}],"answer":0},{"id":"GEO-06","area":"Geotechnical Engineering","topic":"Shear strength","prompt":"A soil has an effective cohesion of 15 kPa and an effective friction angle of 28 degrees. What shear strength is available at an effective normal stress of 120 kPa?","kind":"mc","diff":2,"units":"kPa","steps":["tan(28) = 0.5317","tau = 15 + 120(0.5317) = 15 + 63.81","tau = 78.81 kPa"],"formula":"Mohr-Coulomb: tau = c' + sigma' tan(phi')","note":"","pitfall":"Use EFFECTIVE normal stress with effective parameters. Pairing total stress with c' and phi' overstates the strength, which is unconservative.","choices":[{"text":"63.81","why":"You dropped the cohesion intercept."},{"text":"71.34","why":"Mohr-Coulomb uses the TANGENT of the friction angle, not the sine."},{"text":"78.81","why":null},{"text":"128","why":"The terms are scrambled: cohesion adds directly, and the normal stress is what gets multiplied by tan(phi)."}],"answer":2},{"id":"GEO-07","area":"Geotechnical Engineering","topic":"Bearing capacity","prompt":"A 2 m wide strip footing sits 1.5 m deep in soil with c = 20 kPa, gamma = 18 kN/m^3, and phi = 20 degrees. Using Terzaghi factors Nc = 17.69, Nq = 7.44, and N-gamma = 3.64, what is the ultimate bearing capacity?","kind":"mc","diff":3,"units":"kPa","steps":["Cohesion term: 20(17.69) = 353.8 kPa","Surcharge term: 18(1.5)(7.44) = 200.9 kPa","Width term: 0.5(18)(2)(3.64) = 65.52 kPa","q_ult = 620.2 kPa (allowable at FS = 3 would be 206.7 kPa)"],"formula":"Terzaghi strip footing: q_ult = c Nc + gamma Df Nq + 0.5 gamma B N_gamma","note":"","pitfall":"Only the 0.5*gamma*B term carries the one half. Deeper footings gain capacity through the Nq surcharge term, which is why embedment helps.","choices":[{"text":"206.7","why":"That is the ALLOWABLE capacity after applying a factor of safety of 3. The question asks for ultimate."},{"text":"554.7","why":"You omitted the N-gamma term, which accounts for the footing width."},{"text":"620.2","why":null},{"text":"685.7","why":"The width term carries a factor of one half."}],"answer":2},{"id":"GEO-08","area":"Geotechnical Engineering","topic":"Consolidation and differential settlement","prompt":"A 4 m thick normally consolidated clay layer has Cc = 0.25 and e0 = 0.80. The effective stress at mid-depth increases from 100 kPa to 180 kPa. What is the primary consolidation settlement?","kind":"mc","diff":3,"units":"mm","steps":["Stress ratio = 180 / 100 = 1.8, and log10(1.8) = 0.2553","Cc H / (1 + e0) = 0.25(4) / 1.80 = 0.5556 m","Sc = 0.5556(0.2553) = 0.1418 m = 142 mm"],"formula":"Sc = Cc H / (1 + e0) * log10( (sigma'0 + delta sigma) / sigma'0 )","note":"","pitfall":"log base 10, not ln. Using ln inflates settlement by 2.303. Also note the equation needs the stress at MID-DEPTH of the layer.","choices":[{"text":"-54","why":"The ratio is final over initial stress, so (100 + 80)/100, not 80/100. A ratio below 1 gives a negative settlement."},{"text":"142","why":null},{"text":"255","why":"You omitted the (1 + e0) denominator."},{"text":"327","why":"You used the NATURAL logarithm. The consolidation equation uses log base 10."}],"answer":1},{"id":"GEO-09","area":"Geotechnical Engineering","topic":"Index properties and soil classifications","prompt":"A fine-grained soil has a liquid limit of 48 and a plastic limit of 22. What is its plasticity index, and how does it classify on the plasticity chart (A-line PI = 0.73(LL - 20))?","kind":"mc","diff":3,"units":"","steps":["PI = 48 - 22 = 26","A-line at LL = 48: PI = 0.73(28) = 20.44","26 > 20.44, so the point plots above the A-line -> clay","LL = 48 is below 50, so it is LOW plasticity: CL"],"formula":"PI = LL - PL.  A-line: PI = 0.73(LL - 20).  Above the A-line = clay (C), below = silt (M). LL < 50 gives L (low), LL >= 50 gives H (high).","note":"","pitfall":"Two independent decisions: above/below the A-line picks C versus M, and LL versus 50 picks L versus H. Getting one right and one wrong is the usual outcome.","choices":[{"text":"PI = 26, which plots ABOVE the A-line, so it is a clay (CL)","why":null},{"text":"PI = 26, which plots BELOW the A-line, so it is a silt (ML)","why":"The PI is right but the comparison is not. The A-line at LL = 48 is 0.73(48 - 20) = 20.44, and 26 exceeds it."},{"text":"PI = 70, a high-plasticity clay (CH)","why":"PI is the DIFFERENCE of the limits, not the sum. CH would also require LL of 50 or more."},{"text":"PI = 0.4583, a non-plastic soil","why":"That is a ratio, not the plasticity index."}],"answer":0},{"id":"GEO-10","area":"Geotechnical Engineering","topic":"Laboratory and field tests","prompt":"A field density test gives a dry unit weight of 17.2 kN/m^3. The Proctor maximum dry unit weight is 18.5 kN/m^3. What is the relative compaction?","kind":"num","diff":1,"units":"%","steps":["RC = 17.2 / 18.5 x 100","RC = 92.97%"],"formula":"Relative compaction (%) = gamma_d,field / gamma_d,max x 100","note":"","pitfall":"Relative compaction is NOT relative density (Dr), which uses void ratios e_max and e_min and applies to granular soils. Specifications usually call for 95% relative compaction, so this test fails.","answer":92.97297297297297,"tol":0.01},{"id":"GEO-11","area":"Geotechnical Engineering","topic":"Slope stability","prompt":"An infinite slope in dry cohesionless sand has a friction angle of 32 degrees and a slope angle of 18 degrees. What is the factor of safety against sliding?","kind":"mc","diff":2,"units":"","steps":["tan(32) = 0.6249, tan(18) = 0.3249","FS = 0.6249 / 0.3249 = 1.923","A dry sand slope is stable for any slope angle less than phi"],"formula":"Dry cohesionless infinite slope: FS = tan(phi) / tan(beta). FS is independent of depth and unit weight.","note":"","pitfall":"With seepage parallel to the slope, FS is roughly halved (multiply by gamma'/gamma_sat). Dry and seeping slopes are very different problems.","choices":[{"text":"0.52","why":"You inverted the ratio. A friction angle larger than the slope angle must give FS greater than 1."},{"text":"1.715","why":"The infinite-slope relation uses tangents."},{"text":"1.778","why":"Use the TANGENTS of the angles, not the angles themselves."},{"text":"1.923","why":null}],"answer":3},{"id":"GEO-12","area":"Geotechnical Engineering","topic":"Foundation types","prompt":"A 0.40 m diameter driven pile is 12 m long. Average unit skin friction is 45 kPa and the unit end bearing is 1200 kPa. What is the ultimate axial capacity?","kind":"mc","diff":3,"units":"kN","steps":["Shaft surface area = pi(0.40)(12) = 15.08 m^2","Q_skin = 15.08(45) = 678.6 kN","Tip area = pi(0.40)^2/4 = 0.1257 m^2, so Q_end = 1200(0.1257) = 150.8 kN","Q_ult = 678.6 + 150.8 = 829.4 kN"],"formula":"Q_ult = Q_skin + Q_end = (pi d L) f_s + (pi d^2 / 4) q_p","note":"","pitfall":"Perimeter (pi*d) for the shaft, AREA (pi*d^2/4) for the tip. Mixing these is the most common pile-capacity error.","choices":[{"text":"150.8","why":"That is end bearing only. For a long slender pile, skin friction usually dominates."},{"text":"218.7","why":"You used the cross-sectional AREA for the shaft instead of the perimeter. Skin friction acts on the surface: pi*d*L."},{"text":"678.6","why":"That is skin friction only. Add the end bearing."},{"text":"829.4","why":null}],"answer":3},{"id":"TRA-01","area":"Transportation Engineering","topic":"Geometric design","prompt":"Using SSD = 0.278 V t + V^2 / (254 f), find the stopping sight distance for 90 km/h, a 2.5 s reaction time, and a friction factor of 0.35 on a level road.","kind":"mc","diff":2,"units":"m","steps":["Reaction: 0.278(90)(2.5) = 62.55 m","Braking: 90^2 / (254 x 0.35) = 8100 / 88.9 = 91.11 m","SSD = 62.55 + 91.11 = 153.7 m"],"formula":"SSD = 0.278 V t + V^2 / (254 (f +/- G)), V in km/h.  Downgrade subtracts G, upgrade adds G.","note":"","pitfall":"A DOWNGRADE lengthens SSD because G is subtracted from f. Sign errors on grade are the main trap, and they are always unconservative.","choices":[{"text":"62.55","why":"That is only the reaction distance; the braking distance is missing."},{"text":"63.56","why":"The speed is SQUARED in the braking term."},{"text":"91.11","why":"You omitted the perception-reaction distance, which is 62.55 m at this speed."},{"text":"153.7","why":null}],"answer":3},{"id":"TRA-02","area":"Transportation Engineering","topic":"Geometric design","prompt":"Using R = V^2 / (127(e + f)), what minimum radius is required for 100 km/h with a superelevation of 0.08 and a side friction factor of 0.12?","kind":"num","diff":2,"units":"m","steps":["e + f = 0.08 + 0.12 = 0.2","R = 100^2 / (127 x 0.20) = 10,000 / 25.4","R = 393.7 m"],"formula":"R_min = V^2 / (127 (e + f)), V in km/h, e and f as decimals","note":"","pitfall":"Enter e as 0.08, not 8. Using percent inflates the denominator by 100 and gives an absurdly small radius.","answer":393.70078740157476,"tol":0.02},{"id":"TRA-03","area":"Transportation Engineering","topic":"Geometric design","prompt":"A crest vertical curve joins a +2.0% grade to a -3.0% grade. For a design K value of 50, what curve length is required?","kind":"num","diff":2,"units":"m","steps":["A = |-3.0 - (+2.0)| = 5 percent","L = 50(5) = 250 m"],"formula":"L = K A, where A = |G2 - G1| in percent","note":"","pitfall":"A is the ALGEBRAIC difference, so opposing grades ADD. Treating it as 3 - 2 = 1 gives 50 m instead of 250 m, a fivefold error.","answer":250.0,"tol":0.01},{"id":"TRA-04","area":"Transportation Engineering","topic":"Traffic capacity and flow theory","prompt":"A freeway lane carries a density of 25 veh/km at an average speed of 80 km/h. What is the flow rate?","kind":"mc","diff":1,"units":"veh/h","steps":["q = 25 veh/km x 80 km/h","q = 2,000 veh/h","This is near the typical capacity of about 2000 to 2400 veh/h/lane"],"formula":"Fundamental relation: q = k v  (flow = density x speed)","note":"","pitfall":"Flow is maximized at a MIDDLE density, not the highest. Very high density means congestion, where speed collapses and flow drops.","choices":[{"text":"0.3125","why":"Inverted, and this gives units of veh-h/km^2."},{"text":"3.2","why":"You divided. The fundamental relation is a product: q = k v."},{"text":"105","why":"Adding a density and a speed is dimensionally meaningless."},{"text":"2,000","why":null}],"answer":3},{"id":"TRA-05","area":"Transportation Engineering","topic":"Traffic capacity and flow theory","prompt":"An hourly volume of 2400 veh/h has a peak 15-minute count of 700 vehicles. What is the peak hour factor?","kind":"mc","diff":2,"units":"","steps":["Equivalent hourly flow rate = 4(700) = 2,800 veh/h","PHF = 2400 / 2,800 = 0.857"],"formula":"PHF = hourly volume / (4 x peak 15-minute volume)","note":"","pitfall":"PHF is always between 0.25 and 1.00. A value above 1.0 means you inverted it. Perfectly uniform flow gives exactly 1.0.","choices":[{"text":"0.292","why":"That is the fraction of the hour's volume in the peak quarter, not the PHF."},{"text":"0.857","why":null},{"text":"1.167","why":"Inverted. PHF cannot exceed 1.0."},{"text":"3.429","why":"You omitted the factor of 4 that converts the 15-minute count to an equivalent hourly rate."}],"answer":1},{"id":"TRA-06","area":"Transportation Engineering","topic":"Pavement system design","prompt":"A flexible pavement has 4 in of asphalt concrete (layer coefficient 0.44) over 8 in of granular base (0.14). What is the structural number?","kind":"num","diff":2,"units":"","steps":["Asphalt: 0.44(4) = 1.76","Base: 0.14(8) = 1.12","SN = 1.76 + 1.12 = 2.88"],"formula":"SN = sum(a_i D_i), with D in inches","note":"","pitfall":"Layers below the base carry a drainage coefficient m_i as well: SN = a1 D1 + a2 D2 m2 + a3 D3 m3. Here m was not given, so it is taken as 1.0.","answer":2.88,"tol":0.01},{"id":"TRA-07","area":"Transportation Engineering","topic":"Traffic control devices","prompt":"A two-phase signal has critical lane volumes of 600 and 500 veh/h with a saturation flow of 1800 veh/h per lane and 12 s of total lost time. Using Webster's equation C = (1.5L + 5) / (1 - Y), what is the optimum cycle length?","kind":"mc","diff":3,"units":"s","steps":["Y = 600/1800 + 500/1800 = 0.6111","1 - Y = 0.3889","C = (1.5 x 12 + 5) / 0.3889 = 23 / 0.3889 = 59.14 s"],"formula":"Y = sum(q_i / s_i) over critical movements ;  C_opt = (1.5 L + 5)/(1 - Y)","note":"","pitfall":"If Y reaches or exceeds 1.0 the intersection is oversaturated and no cycle length works. Webster's formula returns a negative or infinite answer, which is the signal to add capacity instead.","choices":[{"text":"23","why":"You omitted the denominator entirely."},{"text":"34.5","why":"You used only one critical movement. Y sums the flow ratios of ALL critical phases."},{"text":"37.64","why":"You divided by Y instead of (1 - Y). As Y approaches 1, the cycle must grow without bound."},{"text":"59.14","why":null}],"answer":3},{"id":"TRA-08","area":"Transportation Engineering","topic":"Transportation planning","prompt":"Traffic of 10,000 vehicles per day is growing at 5% per year, compounded. What is the volume after 10 years?","kind":"mc","diff":2,"units":"veh/day","steps":["(1.05)^10 = 1.6289","Volume = 10,000(1.6289) = 16,289 veh/day"],"formula":"Future volume = present x (1 + growth rate)^n","note":"","pitfall":"Compound and simple growth diverge quickly. At 5% over 20 years the gap is about 15%, which can flip a lane-count decision.","choices":[{"text":"5,000","why":"That is only the increment, and computed simply at that."},{"text":"15,000","why":"That is SIMPLE growth. Compounded growth gives a larger figure."},{"text":"15,513","why":"Off by one year in the exponent."},{"text":"16,289","why":null}],"answer":3},{"id":"TRA-09","area":"Transportation Engineering","topic":"Transportation planning","prompt":"A road segment had 12 crashes over 3 years with an ADT of 15,000. What is the crash rate per million entering vehicles?","kind":"mc","diff":3,"units":"crashes/MEV","steps":["Exposure = 15,000 x 365 x 3 = 16,425,000 vehicles","= 16.43 million entering vehicles","Rate = 12 / 16.43 = 0.731 crashes per MEV"],"formula":"Rate = (crashes x 1,000,000) / (ADT x 365 x years)","note":"","pitfall":"Normalizing by exposure is the whole point. A high-volume road with more total crashes can be SAFER per vehicle than a quiet one.","choices":[{"text":"0.731","why":null},{"text":"2.192","why":"You used one year of exposure instead of three."},{"text":"4","why":"That is crashes per year, which is not normalized by traffic volume at all."},{"text":"800","why":"You omitted the days and years, so exposure is a single day's traffic."}],"answer":0},{"id":"TRA-10","area":"Transportation Engineering","topic":"Traffic control devices","prompt":"At a four-way stop-controlled intersection, two vehicles arrive at the same instant on perpendicular approaches. Who has the right of way?","kind":"mc","diff":1,"units":"","steps":["Both vehicles stop, so neither has priority from arrival order","The tie-break rule is to yield to the right","A left-turning vehicle additionally yields to oncoming through traffic"],"formula":"Simultaneous arrival at an all-way stop: yield to the vehicle on the right.","note":"","pitfall":"Right-of-way is about who must YIELD, never who is entitled to proceed. No one ever 'has' right of way in a way that excuses a collision.","choices":[{"text":"The vehicle on the right","why":null},{"text":"The vehicle on the left","why":"The convention in the United States yields to the right, not the left."},{"text":"The vehicle traveling straight, regardless of position","why":"That rule governs a left-turning versus oncoming conflict, not simultaneous arrival at a stop."},{"text":"The vehicle on the roadway with the higher functional classification","why":"Classification governs which approach gets the stop sign in the first place, not the tie-break once both have stopped."}],"answer":0},{"id":"TRA-11","area":"Transportation Engineering","topic":"Pavement system design","prompt":"Rigid (concrete) and flexible (asphalt) pavements distribute wheel loads differently. Which statement is correct?","kind":"mc","diff":2,"units":"","steps":["Concrete slabs are stiff in bending, so they act as a structural plate","The plate distributes the wheel load over many times the contact area","Asphalt layers are comparatively flexible, so stress reduces gradually with depth and the subgrade does more of the work"],"formula":"Rigid: load carried in slab flexure, low subgrade stress, design on concrete flexural strength. Flexible: load spread through layers, design on subgrade strain and layer thicknesses.","note":"","pitfall":"This is why a weak subgrade hurts flexible pavement far more. It also explains why rigid pavements fail by cracking and flexible ones by rutting.","choices":[{"text":"A rigid slab spreads load over a wide area through slab bending, so subgrade stresses are low and relatively uniform","why":null},{"text":"A rigid slab concentrates load directly beneath the wheel, raising subgrade stress","why":"That describes FLEXIBLE pavement behavior. The slab's stiffness is precisely what spreads the load."},{"text":"A flexible pavement carries load mainly in slab bending","why":"Flexible pavements have negligible bending stiffness; they distribute load through successive granular layers."},{"text":"Subgrade strength is irrelevant to rigid pavement design","why":"Subgrade support still matters; it enters rigid design through the modulus of subgrade reaction k."}],"answer":0},{"id":"CON-01","area":"Construction Engineering","topic":"Project controls","prompt":"A project reports earned value of $450,000, actual cost of $500,000, and planned value of $400,000. What do the cost and schedule performance indices say?","kind":"mc","diff":2,"units":"","steps":["CPI = 450,000 / 500,000 = 0.9 -> less than 1.0, so OVER budget","SPI = 450,000 / 400,000 = 1.125 -> greater than 1.0, so AHEAD of schedule","Cost variance = 450,000 - 500,000 = -$50,000 (unfavorable)","Schedule variance = 450,000 - 400,000 = +$50,000 (favorable)"],"formula":"CPI = EV / AC ;  SPI = EV / PV ;  CV = EV - AC ;  SV = EV - PV. Above 1.0 is favorable.","note":"","pitfall":"Earned value is ALWAYS the numerator. Memorize that one fact and both indices follow, including the sign convention.","choices":[{"text":"CPI = 0.9 and SPI = 1.125, so the project is over budget but ahead of schedule","why":null},{"text":"CPI = 0.9 and SPI = 1.125, so it is under budget but behind schedule","why":"The indices are right but the interpretation is reversed. Below 1.0 is BAD, above 1.0 is GOOD, for both indices."},{"text":"CPI = 1.111 and SPI = 0.8889, over budget and behind schedule","why":"Both indices are inverted. Earned value always goes in the NUMERATOR."},{"text":"CPI = 1 and SPI = 1, on budget and on schedule","why":"Neither index equals 1.0 here."}],"answer":0},{"id":"CON-02","area":"Construction Engineering","topic":"Project controls","prompt":"Activity A (5 days) is followed by both B (3 days) and C (8 days) in parallel. Activity D (6 days) starts only after BOTH B and C finish. What is the project duration?","kind":"mc","diff":2,"units":"days","steps":["Path A-B-D = 5 + 3 + 6 = 14 days","Path A-C-D = 5 + 8 + 6 = 19 days","The longer path governs, so the duration is 19 days","The critical path is A-C-D"],"formula":"Project duration = length of the longest (critical) path through the network.","note":"","pitfall":"Parallel activities do not add. The merge point waits for the SLOWEST predecessor, which is why only the longest path matters.","choices":[{"text":"13","why":"You stopped at C and never added D, which still has to follow the merge."},{"text":"14","why":"That is the A-B-D path, which is not critical. D must wait for C as well."},{"text":"19","why":null},{"text":"22","why":"You summed every activity. B and C run in PARALLEL, so only the longer one controls."}],"answer":2},{"id":"CON-03","area":"Construction Engineering","topic":"Project controls","prompt":"In that same network (A 5 days, then B 3 days and C 8 days in parallel, then D), what is the total float of activity B?","kind":"mc","diff":3,"units":"days","steps":["B's earliest start = 5 (right after A)","D cannot start until 13 (when C finishes), so B's latest finish is 13","B's latest start = 13 - 3 = 10","Total float = 10 - 5 = 5 days"],"formula":"Total float = LS - ES = LF - EF.  Activities on the critical path have zero float.","note":"","pitfall":"Total float is shared along a chain; consuming it on one activity reduces it for the others. FREE float is the part you can consume without affecting any successor.","choices":[{"text":"0","why":"Zero float would mean B is critical. The critical path runs through C, so B has slack."},{"text":"5","why":null},{"text":"8","why":"That is C's duration, not B's float."},{"text":"10","why":"You added A's duration into the float. Float is the difference between late and early start, and both already include A."}],"answer":1},{"id":"CON-04","area":"Construction Engineering","topic":"Construction operations and methods","prompt":"An excavator has a 1.5 m^3 bucket and a 30 second cycle time, working at 83% efficiency. What is its hourly production?","kind":"mc","diff":2,"units":"m^3/h","steps":["Cycles per hour = 3600 / 30 = 120","Theoretical = 1.5(120) = 180 m^3/h","Apply efficiency: 180 x 0.83 = 149.4 m^3/h"],"formula":"Production = bucket volume x cycles per hour x efficiency ;  cycles per hour = 3600 / cycle time in seconds","note":"","pitfall":"A 50 minute working hour is 0.83 efficiency. Also check whether the bucket volume is BANK or LOOSE measure, because that changes the answer by the swell factor.","choices":[{"text":"2.49","why":"You used 60 instead of 3600. With a cycle in SECONDS you need seconds per hour."},{"text":"37.35","why":"You multiplied by cycle time instead of dividing into 3600 s."},{"text":"149.4","why":null},{"text":"180","why":"You ignored the efficiency factor. Real operations never achieve 60 productive minutes per hour."}],"answer":2},{"id":"CON-05","area":"Construction Engineering","topic":"Construction estimating","prompt":"1000 m^3 of soil is measured in its bank (in-place) state. The swell is 25% and the shrinkage is 10%. What are the loose and compacted volumes?","kind":"mc","diff":2,"units":"","steps":["Loose = 1000(1.25) = 1,250 m^3 - this is what you haul","Compacted = 1000(0.90) = 900 m^3 - this is what you place","So 1000 m^3 of cut yields only 900 m^3 of embankment"],"formula":"Loose = bank (1 + swell) ;  Compacted = bank (1 - shrinkage). Bank is the reference state.","note":"","pitfall":"Haul is paid on LOOSE volume, excavation on BANK volume, and embankment on COMPACTED volume. Three different numbers for the same dirt, and quoting the wrong one loses money.","choices":[{"text":"Loose 1,250 m^3, compacted 900 m^3","why":null},{"text":"Loose 900 m^3, compacted 1,250 m^3","why":"The two are swapped. Excavating LOOSENS soil (volume up); compacting DENSIFIES it (volume down)."},{"text":"Loose 800 m^3, compacted 900 m^3","why":"You divided for swell. Loose volume is larger than bank volume, so multiply by 1 + swell."},{"text":"Loose 1,250 m^3, compacted 1,125 m^3","why":"Shrinkage is referenced to BANK volume, not to the loose volume."}],"answer":0},{"id":"CON-06","area":"Construction Engineering","topic":"Construction estimating","prompt":"A footing measures 3.0 m by 2.0 m by 0.6 m thick. Including 5% waste, how much concrete should be ordered?","kind":"num","diff":1,"units":"m^3","steps":["Neat volume = 3.0(2.0)(0.6) = 3.6 m^3","With 5% waste = 3.6(1.05) = 3.78 m^3"],"formula":"Order quantity = neat volume x (1 + waste allowance)","note":"","pitfall":"Ready-mix is usually sold in fixed increments (often 0.5 m^3), so the practical order rounds UP. Rounding down guarantees a second truck.","answer":3.78,"tol":0.01},{"id":"CON-07","area":"Construction Engineering","topic":"Project administration","prompt":"An owner wants a single entity contractually responsible for both design and construction, with one point of accountability for defects. Which project delivery method fits?","kind":"mc","diff":2,"units":"","steps":["The requirement is single-point responsibility spanning design AND construction","Only design-build puts both scopes under one contract","This removes the owner from design-versus-construction disputes, which is the main reason owners choose it"],"formula":"Design-bid-build: owner holds two contracts. Design-build: one contract for both. CMAR: builder joins early at risk, designer stays separate.","note":"","pitfall":"Design-build transfers risk but reduces the owner's control over design detail. The trade-off, not the label, is what the FE tests.","choices":[{"text":"Design-build","why":null},{"text":"Design-bid-build","why":"This is the traditional method, with SEPARATE design and construction contracts. Gaps between them become the owner's problem."},{"text":"Construction management at risk with a separate designer","why":"CMAR brings the builder in early and gives a guaranteed maximum price, but the designer still holds a separate contract with the owner."},{"text":"Multiple prime contracts","why":"That multiplies the owner's contractual relationships, which is the opposite of what was asked."}],"answer":0},{"id":"CON-08","area":"Construction Engineering","topic":"Construction operations and methods","prompt":"A worker must enter a 2.0 m deep trench in previously disturbed soil. What is required before entry?","kind":"mc","diff":2,"units":"","steps":["At 2.0 m the trench exceeds the threshold where protection is mandatory","Previously disturbed soil cannot be classified as stable rock or Type A","Select sloping, benching, shoring, or a trench shield sized for the actual soil class"],"formula":"Excavation protection is required at depths of roughly 1.5 m (5 ft) or more. Options: slope, bench, shore, or shield. A competent person inspects daily.","note":"","pitfall":"Trench collapse is among the deadliest construction hazards because soil is far heavier than people expect - roughly a tonne per cubic metre.","choices":[{"text":"A protective system - sloping, benching, shoring, or shielding - designed for the soil conditions","why":null},{"text":"Nothing, since the trench is less than 3 m deep","why":"There is no blanket shallow exemption. Protection is required at and above about 1.5 m (5 ft), and this trench is deeper than that."},{"text":"Only a competent person's visual inspection, with no physical system","why":"Inspection is required IN ADDITION to protection, never instead of it."},{"text":"A safety harness and lanyard worn by the worker","why":"Fall protection does not prevent a cave-in. A collapse buries the worker regardless of a harness."}],"answer":0},{"id":"CON-09","area":"Construction Engineering","topic":"Construction estimating","prompt":"A crew costs $2,800 per day and places 160 m^2 of formwork per day. What is the unit cost of formwork?","kind":"num","diff":1,"units":"$/m^2","steps":["Unit cost = 2,800 / 160","= $17.5 per m^2"],"formula":"Unit cost = crew cost per day / daily output","note":"","pitfall":"Doubling crew size rarely halves unit cost. Congestion and supervision limits mean output grows more slowly than cost, which is why crew balance matters.","answer":17.5,"tol":0.01},{"id":"CON-10","area":"Construction Engineering","topic":"Interpretation of engineering drawings","prompt":"A drawing is labeled at a scale of 1:50. A wall measures 60 mm on the drawing. What is its actual length?","kind":"mc","diff":1,"units":"","steps":["60 mm x 50 = 3000 mm","3000 mm = 3.0 m","Check the direction: the real wall must be bigger than the paper, so multiply"],"formula":"Actual = drawing measurement x scale denominator. At 1:50, 1 mm on paper is 50 mm in reality.","note":"","pitfall":"Always verify the drawing has not been printed to a different size. A scaled PDF printed on the wrong paper makes every measurement wrong, which is why drawings carry a graphic scale bar.","choices":[{"text":"3.0 m","why":null},{"text":"0.3 m","why":"Off by a factor of 10. 60 mm x 50 = 3000 mm, which is 3.0 m, not 0.3 m."},{"text":"30 m","why":"Off by a factor of 10 the other way. Check the millimetre to metre conversion."},{"text":"1.2 m","why":"That would be 60 mm divided by 50. At 1:50 the real object is LARGER than the drawing, so you multiply."}],"answer":0}]};
